window.MANUAL={"pages":[{"id":"p01","printed":null,"ratio":1.4527,"blocks":[{"t":"h1","text":"BETRIEBSANLEITUNG"},{"t":"p","text":"McCORMICK INTERNATIONAL"},{"t":"p","text":"DIESELSCHLEPPER"},{"t":"p","text":"323"}]},{"id":"p02","printed":null,"ratio":1.4512,"blocks":[{"t":"h1","text":"BETRIEBSANLEITUNG"},{"t":"p","text":"McCORMICK INTERNATIONAL"},{"t":"p","text":"323"},{"t":"p","text":"DIESELSCHLEPPER"},{"t":"p","text":"INTERNATIONAL HARVESTER COMPANY M.B.H."},{"t":"p","text":"NEUSS UND HEIDELBERG"}]},{"id":"p03","printed":"2","ratio":1.6612,"blocks":[{"t":"fig","label":"","caption":"Mc CORMICK INTERNATIONAL 323 Dieselschlepper linke Seite","legend":[],"src":"ba/fig/p03-1.jpg","w":1100,"h":756},{"t":"fig","label":"","caption":"Mc CORMICK INTERNATIONAL 323 Dieselschlepper rechte Seite","legend":["1 - Motornummer ..................","2 - Fahrgestellnummer ............","3 - Getriebenummer...............","4 - Krafthebernummer............."],"src":"ba/fig/p03-2.jpg","w":1100,"h":666}]},{"id":"p04","printed":"3","ratio":1.4851,"blocks":[{"t":"h1","text":"Inhaltsverzeichnis"},{"t":"table","caption":"Inhaltsverzeichnis","head":["Abschnitt","Seite"],"rows":[["Technische Einzelheiten","4"],["Geschwindigkeitstabellen","5, 6"],["Wichtige Ratschläge","7"],["Bedienungs- und Kontrollelemente","8"],["– Armaturen","8"],["– Bedienungshebel","9"],["Fahrbetrieb","12"],["– Prüfungen vor täglichem Arbeitsbeginn","12"],["– Anlassen des Motors","12"],["– Anfahren des Schleppers","12"],["– Gasregulierung","12"],["– Abstellen des Motors","13"],["– Winterbetrieb","13"],["– Führersitz","13"],["– Wasserfüllung der Hinterreifen","14"],["– Unfallverhütung","16"],["Zapfwelle, Zugvorrichtung und Regelhydraulik","17"],["– Zapfwelle","17"],["– Zugvorrichtungen","17"],["– Dreipunktaufhängung","18"],["– Regelhydraulik","19"],["– Blocksteuergerät","21"],["Wartung und Pflege","23"],["– Regelmäßige Wartungs- und Pflegearbeiten","23"],["– Schmierplan","24"],["– Abnehmen der Motorhaube","26"],["– Ölbadluftfilter","26"],["– Kraftstoffsystem","27"],["– Motorölwechsel","36"],["– Erneuern des Motorölfilters","32"],["– Kühlsystem","32"],["– Getriebeölwechsel","35"],["– Pflege der Regelhydraulik","37"],["– Lenkgetriebe","38"],["– Abschmieren","38"],["Einstellungen","39"],["– Kupplung","39"],["– Nachstellen der Lamellenkupplung","39"],["– Bremsen","40"],["– Spurverstellung der Vorderräder","41"],["– Einstellen der Vorspur","41"],["– Nachstellen der Vorderradlager","42"],["– Spurverstellung der Hinterräder","43"],["Elektrische Anlage","45"],["– Schaltschema","47"],["Behandlung des Schleppers bei längeren Arbeitspausen","51"],["Betriebsstörungen am Motor und deren Ursachen","52"],["Stichwortverzeichnis","53"]]}]},{"id":"p05","printed":"4","ratio":1.5262,"blocks":[{"t":"h1","text":"Technische Einzelheiten"},{"t":"h2","text":"Motor"},{"t":"table","caption":"Motor","head":["",""],"rows":[["","3-Zylinder Viertakt-Dieselmotor DD-111"],["Nenndrehzahl","1900 U/min"],["Max. Drehzahl ohne Belastung","2050 U/min"],["Max. Drehmoment bei 1400 U/min","9,8 mkg"],["Untere Leerlaufdrehzahl","500-600 U/min"],["Dauerleistung","24,3 PS"],["Hubraum","1825 cm³"],["Bohrung","87,3 mm"],["Hub","101,6 mm"],["Zündfolge","1-3-2"],["Ventilspiel (bei warmem Motor)","0,3 mm"],["Batterie","eine: 12V 84 AH"],["Düsenhalter","Bosch KB 47 SA 410/1"],["Einspritzdüsen","Bosch-Zapfendüsen"],["Einspritzdruck","150 atü"],["Einspritzpumpe","Bosch-Reiheneinspritzpumpe PES 3M65 C320/3 LS35y"],["Anlasser","Bosch EJD 1,8/12 R61"],["Lichtmaschine","Bosch LJ/GEH 90/12/1800"],["Einfachkupplung","Einscheiben-Trockenkupplung 225 mm Ø"],["Zweifachkupplung","Zweischeiben-Trockenkupplung 225 mm Ø"],["Motorzapfwelle (Zweifachkupplung)","542 U/min"],["Motorzapfwelle (Einfachkupplung)","577 U/min"]]},{"t":"h2","text":"Füllmengen"},{"t":"table","caption":"Füllmengen","head":["",""],"rows":[["Ölfüllung für Motor","4,1 Liter"],["Ölfüllung für Getriebe","34 Liter"],["Ölfüllung für Krafthebergehäuse","12,8 Liter"],["Ölfüllung für Ölbadluftfilter","ca. 0,35 Liter"],["Kraftstoffbehälter","60 Liter"],["Kühlsystem","7,5 Liter"]]},{"t":"h2","text":"Bereifung"},{"t":"h3","text":"Reifendruck"},{"t":"table","caption":"Reifendruck","head":["","Acker","Straße"],"rows":[["Vorderräder","1,5 - 2,0 atü","2,0 atü"],["Hinterräder","0,8 - 1,0 atü","1,5 atü"]]},{"t":"h3","text":"Spurverstellung"},{"t":"table","caption":"Spurverstellung","head":["",""],"rows":[["Vorderachse und Räder","1220 mm - 1860 mm"],["Hinterräder","1280 mm - 1880 mm"]]},{"t":"h2","text":"Abmessungen des Schleppers"},{"t":"table","caption":"Abmessungen des Schleppers","head":["",""],"rows":[["Länge über alles","2960 mm"],["Breite über alles","1522 mm, bei kleinster Spurbreite"],["Kleinste Höhe bis Lenkradoberkante","1434 mm"],["Radstand","1815 mm"],["Kleinste Bodenfreiheit","372 mm"],["Kleinster Spurkreishalbmesser","3180 mm"],["Kleinster Spurkreishalbmesser mit Lenkbremse","2780 mm"]]}]},{"id":"p06","printed":"5","ratio":1.4904,"blocks":[{"t":"h1","text":"Tabelle I"},{"t":"table","caption":"Fahrgeschwindigkeiten für Schlepper mit Wandlergetriebe und 9x36 Hinterradbereifung","head":["Gruppe","Ackergruppe","","","","","Straßengruppe","","","",""],"rows":[["Gang","1","2","3","4","R1","5","6","7","8","R2"],["Schnell km/h","2,0","3,9","6,2","7,7","3,3","5,2","10,1","16,1","20,0","8,6"],["Langsam km/h","1,4","2,8","4,5","5,6","2,4","3,7","7,3","11,7","14,7","6,3"]]},{"t":"p","text":"Die untere Abbildung zeigt symbolisch, welche Stellung die Schalthebel haben müssen, um eine gewünschte Geschwindigkeit zu erreichen."},{"t":"fig","label":"","caption":"","legend":["Ackergruppe / Straßengruppe – Gruppenschalthebel","R1 R2, 2 6, 4 8, 1 5, 3 7 – Gangschalthebel","Langsam / Schnell – Schaltgriff-Wandlergetriebe","Skala: 8,6  6,3  3,3  2,4  0  1,4  2,0  2,8  3,7  3,9  4,5  5,2  5,6  6,2  7,3  7,7  10,1  11,7  14,7  16,1  20 km/h","Rückwärts ← → Vorwärts","0207"],"src":"ba/fig/p06-1.jpg","w":1100,"h":634}]},{"id":"p07","printed":"6","ratio":1.5101,"blocks":[{"t":"h1","text":"Tabelle II"},{"t":"table","caption":"Fahrgeschwindigkeiten für Schlepper mit Agriomatic und 9 x 36 Hinterradbereifung","head":["Gruppe","Ackergruppe","","","","","Straßengruppe","","","",""],"rows":[["Gang","1","2","3","4","R1","5","6","7","8","R2"],["km/h","1,9","3,7","5,8","7,3","3,1","4,9","9,6","15,3","20,0","8,2"]]},{"t":"p","text":"Die untere Abbildung zeigt symbolisch, welche Stellung die Schalthebel haben müssen, um eine gewünschte Geschwindigkeit zu erreichen."},{"t":"fig","label":"","caption":"","legend":["Ackergruppe / Neutral / Straßengruppe – Agriomatic-Hebel","R1 R2, 2 6, 4 8, 1 5, 3 7 – Gangschalthebel","Skala: 8,2  3,1  0  1,9  3,7  4,9  5,8  7,3  9,6  15,3  20 km/h","Rückwärts ← → Vorwärts","0222"],"src":"ba/fig/p07-1.jpg","w":1100,"h":528},{"t":"p","text":"Die Zahlen 1-8, R1 und R2 in den beiden Abbildungen entsprechen den Gängen 1-4 und R1 in der Ackergruppe bzw. 5-8 und R2 in der Straßengruppe."},{"t":"p","text":"Bei anderen Reifenabmessungen ändern sich die Fahrgeschwindigkeiten, Schnelläufer erreichen in der Straßengruppe je nach Bereifung bis 30 km/h."}]},{"id":"p08","printed":"7","ratio":1.4633,"blocks":[{"t":"h1","text":"Wichtige Ratschläge"},{"t":"list","ordered":true,"items":["Vor Inbetriebnahme des Schleppers dieses Handbuch gewissenhaft studieren. Alle Anweisungen im eigenen Interesse genauestens befolgen. Alle Bedienungshebel und ihre Funktion einprägen und am stehenden Schlepper ausprobieren.","Den neuen Schlepper nicht sofort bei Inbetriebnahme voll belasten. Erst nach wenigstens 50stündiger Betriebsdauer dem Schlepper die volle Leistung abverlangen. Nie überlasten, sonst treten frühzeitiger Verschleiß und Bruch ein, und die Fabrikgarantie erlischt.","Den Schlepper nach dem Schmierplan vorschriftsmäßig abschmieren. Dabei beachten, daß alle Schmiernippel Fett durchlassen.","Kraftstoffbehälter nicht bei laufendem Motor oder in der Nähe offener Lampen oder irgendwelchem Feuer auffüllen.","In den Kühler kein kaltes Wasser einfüllen, solange der Motor heiß ist.","Das Kupplungspedal nicht als Fußrast benutzen, da dies einen frühzeitigen Verschleiß aller Kupplungsteile zur Folge haben würde.\nBeim Anhalten der Zapfwelle die Handkupplung (wenn vorhanden) nur kurz betätigen, um übermäßigen Verschleiß des Drucklagers zu vermeiden.","Die zu ziehenden Lasten nur an die Anhängevorrichtungen anhängen.","Die Bereifung auf den vorschriftsmäßigen Luftdruck für Ackerarbeit oder Straßentransport aufpumpen.","Den Schlepper regelmäßig überprüfen und Mängel sofort beseitigen.","Den Schlepper sauberhalten. Vorsicht beim Abspritzen mit Druckwasser an Einspritzpumpe, Lichtmaschine und Anlasser.","Überholungsarbeiten und Reparaturen sowie Arbeiten an \"Bosch\"-Erzeugnissen nur von Fachleuten oder sachkundigen Monteuren ausführen lassen.","Bei Frostwetter Kühlwasser und evtl. Wasserfüllung der Hinterradreifen gegen Einfrieren schützen. Näheres unter Frostschutz.","Bei niedrigen Außentemperaturen den Motor nach dem Anlassen einige Minuten mit halber Drehzahl warmlaufen lassen, bevor der Schlepper belastet wird.","Muß die Regelhydraulik in Ausnahmefällen sofort betätigt werden, den Motor ebenfalls nur mit halber Drehzahl laufen lassen.","Die Inspektionen nach dem Kundendienstscheckheft gewissenhaft durchführen lassen."]}]},{"id":"p09","printed":"8","ratio":1.5826,"blocks":[{"t":"h1","text":"Bedienungs- und Kontrollelemente"},{"t":"h2","text":"Armaturen"},{"t":"p","text":"Alle Kontrollelemente sind im Traktormeter und im Kombiinstrument übersichtlich zusammengefaßt."},{"t":"fig","label":"Bild 1","caption":"","legend":["1 - Traktormeter","2 - Kombiinstrument","3 - Blinklicht- und Abblendschalter","4 - Signalhorn"],"src":"ba/fig/p09-1.jpg","w":652,"h":509},{"t":"h2","text":"Traktormeter"},{"t":"fig","label":"Bild 2","caption":"Traktormeter","legend":[],"src":"ba/fig/p09-2.jpg","w":674,"h":686},{"t":"p","text":"Das Traktormeter Bild 2 zeigt die Betriebsstunden, die Motordrehzahl sowie die Fahrgeschwindigkeit an. Die rechte Zahlenrolle des Betriebsstundenzählers, mit roten Zahlen auf weißem Grund, zeigt die Betriebsstunden in Zehnteln an."},{"t":"p","text":"Um Wartungs- und Pflegearbeiten an der Maschine rechtzeitig und gewissenhaft durchführen zu können, ist es ratsam, den jeweiligen Stand des Betriebsstundenzählers aufzuschreiben."},{"t":"p","text":"Die drei Geschwindigkeitsfelder auf dem unteren Teil des Traktormeters zeigen die Höchstgeschwindigkeit in den drei oberen Gängen der Straßengruppe."},{"t":"p","text":"Die Geschwindigkeitstabellen auf Seite 5 und 6 geben die Fahrgeschwindigkeit in den einzelnen Gängen an."},{"t":"h2","text":"Kombiinstrument"},{"t":"p","text":"Im Kombiinstrument sind die Kontrolleuchten, der Kraftstoffanzeiger und das Kühlwasserthermometer angeordnet, die nachstehend im einzelnen beschrieben werden."},{"t":"fig","label":"Bild 3","caption":"","legend":["1 - Fernlichtkontrolleuchte, blau","2 - Kontrolleuchte für Motoröldruck, grün","3 - Ladekontrolleuchte, rot","4 - Kraftstoffanzeiger","5 - Kühlwasserthermometer","6 - Öldruckkontrolleuchte des Wandlergetriebes","7 - Blinkerkontrolleuchte für Schlepper, rot","8 - Blinkerkontrolleuchten für Anhänger, rot"],"src":"ba/fig/p09-3.jpg","w":674,"h":760}]},{"id":"p10","printed":"9","ratio":1.5,"blocks":[{"t":"p","text":"Wird der Schaltkastenschlüssel zum Anlassen des Motors aus der Nullstellung nach rechts auf Stellung 1 gedreht, dann müssen die Kontrolleuchten für Motoröldruck (2), für den Öldruck des Wandlergetriebes (6) und die Ladekontrollampe (3) aufleuchten."},{"t":"h2","text":"Kontrolleuchte für Motoröldruck (2)"},{"t":"p","text":"Sobald der Motor läuft und die Drehzahl erhöht wird, muß die grüne Kontrolleuchte (2) erlöschen."},{"t":"p","text":"Erlischt sie nicht oder leuchtet sie während der Arbeit auf, den Motor abstellen, die Ölversorgung überprüfen und den Fehler beheben; siehe auch \"Betriebsstörungen\"."},{"t":"h2","text":"Ladekontrolleuchte (3)"},{"t":"p","text":"Mit zunehmender Drehzahl erlischt die rote Kontrolleuchte (3). Leuchtet sie weiter oder blinkt sie auf, so ist die elektrische Anlage zu überprüfen."},{"t":"h2","text":"Kühlwasserthermometer (5)"},{"t":"p","text":"Die Kühlwassertemperatur wird durch ein Thermometer (5) angezeigt. Die normale Betriebstemperatur liegt zwischen 80 und 95° C. Übersteigt sie 95° C, die Ursache suchen und beheben; siehe auch \"Betriebsstörungen\"."},{"t":"p","text":"Die günstigste Betriebstemperatur liegt bei 90° C und ist auf dem Kühlwasserthermometer durch einen grünen Strich markiert."},{"t":"h2","text":"Kraftstoffanzeiger"},{"t":"p","text":"Eine Zahlenskala zeigt den Kraftstoffvorrat im Behälter an."},{"t":"h2","text":"Fernlicht- und Blinkerkontrolleuchten"},{"t":"p","text":"Bei eingeschaltetem Fernlicht leuchtet die blaue Kontrolleuchte (1) auf."},{"t":"p","text":"Bei betätigtem Blinkgeber leuchten zunächst alle drei Kontrolleuchten (7 und 8) kurz auf. Es ist ein Kontrollaufblinken, das ein einwandfreies Funktionieren der Anlage anzeigt. Beim Fahren ohne Anhänger erlöschen beide Kontrolleuchten (8), beim Mitführen von nur einem Anhänger erlischt eine der beiden Leuchten (8)."},{"t":"h2","text":"Kontrolleuchte (6) für Öldruck im Wandlergetriebe"},{"t":"p","text":"Das für die Schmierung und Steuerung des Wandlergetriebes erforderliche Öl wird durch eine unabhängige Pumpe in Umlauf gesetzt."},{"t":"p","text":"Die Kontrollampe (6) zeigt durch Aufleuchten an, wenn nicht genügend Öldruck vorhanden ist. Bei niedrigen Motordrehzahlen (Anlassen und Leerlauf) oder wenn die Fußkupplung betätigt wird, ist das Aufleuchten der Kontrollampe normal."},{"t":"p","text":"Leuchtet die Lampe während der Arbeit auf, ohne daß das Kupplungspedal betätigt wurde, so ist der Öldruck zu gering. In diesem Fall den Schaltgriff des Wandlergetriebes auf \"Langsam\" nach vorn schalten."},{"t":"p","text":"Wird hierdurch keine Abhilfe geschaffen, den IH-Kundendienst zu Rate ziehen."},{"t":"p","text":"Anmerkung: Bei Schleppern ohne Wandlergetriebe ist die Kontrollampe (6) nicht vorhanden."},{"t":"h2","text":"Bedienungshebel"},{"t":"fig","label":"Bild 4","caption":"","legend":["1 - Zapfwellenkupplung","2 - Schaltkastenschlüssel","3 - Kupplungspedal","4 - Gangschalthebel","5 - Schaltgriff für Wandlergetriebe","6 - Handbremshebel","7 - Handgashebel","8 - Bremspedale","9 - Feststellasche","10 - Gruppenschalthebel","11 - Gaspedal","12 - Differentialsperre","13 - Schalthebel für Blocksteuergeräte","14 - Blinklicht- und Abblendschalter"],"src":"ba/fig/p10-1.jpg","w":679,"h":484}]},{"id":"p11","printed":"10","ratio":1.6107,"blocks":[{"t":"h2","text":"Gangschalthebel"},{"t":"p","text":"Eine zweckmäßige Anordnung der Schaltelemente und eine besondere Zahnform tragen wesentlich zum leichten Schalten bei."},{"t":"p","text":"Der Gangschalthebel (4) Bild 4 ist immer zu betätigen, wenn ein Gang eingelegt oder gewechselt werden soll. Die Anordnung der Gänge ist auf dem Schalthebelknopf dargestellt, Bild 5."},{"t":"fig","label":"Bild 5","caption":"Ackergänge = weiß 1 - 4 und R1\nStraßengänge = rot 5 - 8 und R2","legend":[],"src":"ba/fig/p11-1.jpg","w":534,"h":453},{"t":"p","text":"Am Punkt \"A\" auf der neutralen Mittellinie ist eine Stufe. Um bei einem Schaltvorgang aus dem rechten weißen Feld in die Gänge 1, 5, R1 und R2 schalten zu können, den Schalthebel leicht anheben."},{"t":"p","text":"Die Stellung des Schalthebels ist in den Gängen 1 - 4 und R1 jeweils die gleiche wie in den Stellungen 5 - 8 und R2. Die Gänge 1 - 4 und R1 zählen zur Ackergruppe für Feldarbeit und schweren Zug und die Gänge 5 - 8 und R2 zur Straßengruppe für Transportarbeit. Maßgebend, ob es sich um Ackergänge oder Straßengänge handelt, ist die Stellung des Agriomatic-Schalthebels oder des Gruppenschalthebels beim Gruppengetriebe."},{"t":"p","text":"Da Rollwiderstand und angehängte Last das Schalten beeinflussen, gehört etwas Übung und Gefühl dazu, geräuschlos herauf und herunter zu schalten."},{"t":"h2","text":"Getriebeausführungen"},{"t":"p","text":"Der Schlepper kann wahlweise mit einem Gruppengetriebe oder dem Agriomaticgetriebe ausgerüstet sein. „Beide Getriebeausführungen haben vier Acker- und vier Straßengänge."},{"t":"p","text":"Das Gruppengetriebe kann zusätzlich mit einem vorgeschalteten Wandlergetriebe und einer Zweifachkupplung für unabhängigen Zapfwellenantrieb ausgerüstet sein."},{"t":"p","text":"Wegen der Unterschiedlichkeit in der Bedienung werden die beiden Getriebeausführungen nacheinander getrennt behandelt."},{"t":"h2","text":"Gruppengetriebe"},{"t":"p","text":"Durch den Gruppenschalthebel werden die Gänge in eine Ackergruppe (1. - 4. Gang und R1) sowie in eine Straßengruppe (5. - 8. Gang und R2) je nach Bedarf geschaltet. Bild 6 zeigt die beiden Schaltstellungen. Der Hebel hat keine Neutralstellung."},{"t":"fig","label":"Bild 6","caption":"Gruppenschalthebel","legend":["1 - Gruppenschalthebel - Straßengruppe","2 - Gruppenschalthebel - Ackergruppe","3 - Zapfwellenschalthebel - Zapfwelle ausgeschaltet","4 - Zapfwellenschalthebel - Zapfwelle eingeschaltet"],"src":"ba/fig/p11-2.jpg","w":653,"h":513},{"t":"p","text":"Den Gruppenschalthebel nur bei stehendem Schlepper und ausgerückter Fußkupplung betätigen. Den Hebel mit Gefühl schalten, damit der Eingriff der Zahnkupplung schonend erfolgt. Nötigenfalls mit der Fußkupplung ein wenig nachhelfen."},{"t":"h2","text":"Wandlergetriebe"},{"t":"p","text":"Schlepper mit Gruppengetriebe können auch mit einem Wandlergetriebe ausgerüstet sein. Es ist dann in allen Gängen eine zusätzliche Geschwindigkeitsabstufung möglich."},{"t":"p","text":"In der Stellung (1) Bild 7 erfolgt in jedem Gang eine Drehmomentverstärkung und damit verbunden eine Verringerung der Fahrgeschwindigkeit."},{"t":"p","text":"In der Stellung 2 fährt der Schlepper schneller."},{"t":"p","text":"Die Fahrgeschwindigkeit des Schleppers kann also während der Arbeit, ohne zu kuppeln, herauf- oder heruntergeschaltet werden."},{"t":"p","text":"Beim Anfahren ist es zweckmäßig, den Schaltgriff in Stellung 1 zu haben und danach in Stellung 2 umzuschalten."},{"t":"p","text":"Fällt während der Fahrt durch zusätzliche Belastung -ansteigendes Gelände und dergl. - die Motordrehzahl ab, den Schaltgriff in Stellung 1 zurückschalten. Dadurch wird ohne Unterbrechung des Kraftflusses ein niedrigeres Übersetzungsverhältnis eingerückt und der Schlepper braucht nicht mittels Fußkupplung und Getriebeschalthebel heruntergeschaltet zu werden."}]},{"id":"p12","printed":"11","ratio":1.5204,"blocks":[{"t":"fig","label":"Bild 7","caption":"Schaltgriff für Wandlergetriebe","legend":["1 - Langsam","2 - Schnell"],"src":"ba/fig/p12-1.jpg","w":568,"h":411},{"t":"p","text":"Nachdem die Steigung überwunden ist, den Schaltgriff auf Stellung 2 zurückschalten und der Schlepper fährt wieder schneller."},{"t":"h2","text":"Agriomatic-Hebel"},{"t":"p","text":"Mit dem Agriomatic-Hebel läßt sich aus der Neutralstellung (1) Bild 8 nach vorn die Ackergruppe (2) und nach hinten die Straßengruppe (3) einschalten. Der Wechsel von der Straßengruppe zur Ackergruppe kann während der Fahrt ohne Fußkupplung erfolgen. Von der Ackergruppe zur Straßengruppe darf nur bei betätigter Kupplung und möglichst bei stehendem Schlepper geschaltet werden."},{"t":"p","text":"Zum leichteren Schalten läßt sich der Schalthebel teleskopartig herausziehen. Dadurch wird besonders das Einrücken der Ackergruppe erleichtert."},{"t":"fig","label":"Bild 8","caption":"Agriomatic-Hebel","legend":["1 - Neutralstellung","2 - Ackergruppe","3 - Straßengruppe"],"src":"ba/fig/p12-2.jpg","w":648,"h":497},{"t":"p","text":"In der Neutralstellung (1) erfolgt kein Fahrantrieb, auch nicht wenn ein Getriebegang eingeschatet ist. Ein Gangwechsel kann in dieser Stellung ohne Betätigen der Fußkupplung erfolgen. Die eingeschaltete Zapfwelle läuft in der Neutralstellung weiter."},{"t":"h2","text":"Differentialsperre"},{"t":"p","text":"Wenn auf schmierigem Boden eines der Hinterräder durchrutscht, läßt sich die Ausgleichwirkung des Differentials durch die Differentialsperre unterbinden, d. h. beide Hinterräder werden nun gleich schnell angetrieben. Die Differentialsperre durch den Fußhebel (12) Bild 4 einschalten. Das Ausschalten erfolgt automatisch durch Federzug, wenn der Fuß vom Fußhebel genommen wird."},{"t":"p","text":"Die Differentialsperre nur vorübergehend zur Überwindung von Gleitstellen und bei Geradeausfahrt benutzen, weil sonst übermäßiger Reifenverschleiß und unnötige Beanspruchung der Differentialteile eintreten könnten."},{"t":"h2","text":"Beleuchtung"},{"t":"p","text":"Scheinwerfer und Begrenzungslampen werden durch den Schlüssel (1) Bild 9 im Schaltkasten eingeschaltet. Bei eingestecktem Schlüssel in Stellung \"O\" sind sämtliche Armaturen und Verbraucher abgeschaltet."},{"t":"p","text":"Nach links in Stellung \"P\" (Parken) kann der Schlüssel nur in eingedrücktem Zustand geschaltet werden. In dieser Stellung brennen Schluß- und Begrenzungslampen. Der Schlüssel kann in dieser Stellung abgezogen werden."},{"t":"p","text":"Wird der Schlüssel nach rechts in Stellung \"1\" geschaltet, so haben sämtliche Armaturen Spannung, und das Signalhorn, die Blinkleuchten, die Steckdose und der Anlasser sind betriebsbereit."},{"t":"p","text":"In der Schaltstellung \"2\" leuchten zusätzlich die Schluß-, Armaturen- und Begrenzungslampen auf."},{"t":"p","text":"Die Scheinwerfer leuchten in Schaltstellung \"3\" auf, die Begrenzungslampen bleiben dabei eingeschaltet."},{"t":"h2","text":"Blinkschalter"},{"t":"p","text":"Mit dem Blinkschalterhebel (14) Bild 4 wird der Blinkgeber betätigt."},{"t":"table","caption":"","head":[],"rows":[["Nach vorn geschaltet","rechte Blinkleuchten."],["Nach hinten geschaltet","linke Blinkleuchten."]]},{"t":"p","text":"Durch kurzes Anheben des Blinkschalterhebels (14) bei eingeschalteten Scheinwerfern wird über ein Relais das Abblendlicht, bzw. Fernlicht eingeschaltet. Bei nicht eingeschalteten Scheinwerfern ergibt das Anheben des Hebels ein Lichtsignal (Lichthupe). Am Ende des Blinkschalterhebels ist der Signalhornknopf angebracht."}]},{"id":"p13","printed":"12","ratio":1.5962,"blocks":[{"t":"h1","text":"Fahrbetrieb"},{"t":"h2","text":"Einlaufen des Schleppers"},{"t":"p","text":"Während der ersten 100 Betriebsstunden den Schlepper schonend behandeln. Dies bezieht sich sowohl auf die Fahrweise und Belastung wie auch auf die Wartungs- und Pflegemaßnahmen."},{"t":"p","text":"Die Kolben, Lager und Getriebeteile können nur dann gut einlaufen, wenn der Schlepper in der ersten Zeit nicht vollbelastet und der Motor nicht mit höchster Drehzahl gefahren wird. Ein allmähliches Steigern der Belastung bei wechselnden Drehzahlen hat sich in der Praxis gut bewährt und ist eine wichtige Voraussetzung für eine lange Lebensdauer des Schleppers."},{"t":"p","text":"Bei der Auslieferung des Schleppers ist der Motor mit Einlauföl gefüllt, das bei der 1. Inspektion nach 20 Betriebsstunden durch reguläres Motoröl ersetzt wird."},{"t":"h2","text":"Prüfungen vor täglichem Arbeitsbeginn"},{"t":"p","text":"Vor dem täglichen Arbeitsbeginn Motorölstand, Kühlwasserstand und Ölstand im Hydraulikgehäuse kontrollieren und, wenn erforderlich, nachfüllen. Blinkanlage, Beleuchtung und Bremsen auf einwandfreies Ansprechen überprüfen."},{"t":"p","text":"Bei sehr staubiger Arbeit den Luftfilter-Vorabscheider täglich reinigen und das Luftfilteröl wechseln."},{"t":"h2","text":"Anlassen des Motors"},{"t":"p","text":"Kraftstoffabsperrhahn (12) Bild 33 öffnen. Gangschalthebel (4) Bild 4 in Neutralstellung bringen. Handgashebel (7) ganz nach hinten auf Vollgas stellen. Schaltkastenschlüssel (1) Bild 9 auf Stellung \"1\" drehen. Dabei müssen Ladekontrolleuchte, Öldruckkontrolleuchte und die Öldruckkontrolleuchte des Wandlergetriebes aufleuchten, wenn der Schlepper mit Wandlergetriebe ausgerüstet ist."},{"t":"fig","label":"Bild 9","caption":"","legend":["1 - Schaltkastenschlüssel","2 - Glühanlaßschalter: Starten","3 - Glühanlaßschalter: Vorglühen"],"src":"ba/fig/p13-1.jpg","w":581,"h":430},{"t":"p","text":"Glühanlaßschalter bis zum Anschlag (3) ziehen und ihn zum Vorglühen 15 bis 20 Sekunden in dieser Stellung halten. Je niedriger die Außentemperatur, desto länger vorglühen."},{"t":"p","text":"Nach dem Vorglühen den Glühanlaßschalter über den Anschlag hinaus ziehen (2), wodurch der Anlasser betätigt wird. Sobald der Motor läuft, Glühanlaßschalter loslassen; er springt selbsttätig auf seine Nullstellung zurück."},{"t":"p","text":"Sollte der Motor 15 Sekunden nach Ziehen des Vorglühschalters nicht angesprungen sein, den gesamten Anlaßvorgang wiederholen: erst vorglühen, dann starten. Den Glühanlaßschalter aber nicht betätigen, solange sich das Schwungrad des Motors noch bewegt. Wird dies nicht beachtet, so können Anlasser und Schwungradzahnkranz beschädigt werden."},{"t":"p","text":"Zur Schonung der Batterie lieber länger vorglühen, als zu oft den Anlasser betätigen."},{"t":"p","text":"Bei bereits warmem Motor genügt kurzes Vorglühen. Ist der Motor angesprungen, Handgashebel auf mittlere Motordrehzahl zurückstellen und den Motor einige Minuten warmlaufen lassen."},{"t":"h2","text":"Anfahren des Schleppers"},{"t":"p","text":"Vor dem Fahren mit dem Schlepper empfiehlt es sich, die Handhabung der einzelnen Schalthebel bei stehendem Schlepper etwas einzuüben."},{"t":"p","text":"Zur Fortbewegung des Schleppers muß das Getriebe mit dem Motor verbunden werden. Dies geschieht mittels der Kupplung. Die Kupplung stets betätigen, wenn ein Gang ein- oder ausgeschaltet werden soll."},{"t":"p","text":"Das Kupplungspedal durchtreten und den gewünschten Gang einlegen. Dabei darf das Kupplungspedal weder zu plötzlich noch übermäßig langsam zurückgelassen werden. Zu plötzliches Einkuppeln verursacht ruckartiges Anfahren, zu langsames Einkuppeln führt zu unnötiger Beanspruchung der Kupplungsbeläge."},{"t":"p","text":"Das Kupplungspedal nicht als Fußrast benutzen, weil dadurch der Kupplungsausrückring unnötig abgenutzt wird."},{"t":"p","text":"Wenn der Schlepper mit einer Agriomatic-Schaltung ausgestattet ist, läßt er sich auch mit dem Agriomatic-Schalthebel anfahren oder anhalten, wenn bereits ein Gang eingeschaltet ist."},{"t":"h2","text":"Gasregulierung"},{"t":"p","text":"Der Handgashebel (7) Bild 4 dient zur Regulierung der Motordrehzahl. Der Fliehkraftverstellregler der Einspritzpumpe sorgt dafür, daß die eingestellte Motordrehzahl auch bei unterschiedlicher Belastung beibehalten wird."},{"t":"p","text":"Die Höchstdrehzahl des Motors ist bei voller Belastung auf etwa 1900 Umdrehungen pro Minute eingestellt. Ohne Belastung erhöht sich die Drehzahl auf etwa 2050 U/min. Die untere Leerlaufdrehzahl beträgt etwa 600 U/min."}]},{"id":"p14","printed":"13","ratio":1.4931,"blocks":[{"t":"p","text":"Bei gleichbleibenden Arbeiten läßt sich die erforderliche Motordrehzahl mit dem Handgashebel einstellen. Andererseits kann die eingestellte Drehzahl nach oben hin mit dem Gaspedal korrigiert werden, wenn der Handgashebel nicht auf Vollgas steht."},{"t":"p","text":"Bei Straßenfahrten oder ähnlichem läßt sich die Motordrehzahl mit dem Gaspedal bequemer regulieren. Der Handgashebel muß dabei auf unterer Leerlaufdrehzahl stehen."},{"t":"h2","text":"Abstellen des Motors"},{"t":"p","text":"Gaspedal freigeben und Handgashebel (7) Bild 4 auf untere Leerlaufdrehzahl, d. h. ganz nach vorn stellen, und der Motor bleibt stehen. Schaltkastenschlüssel abziehen."},{"t":"p","text":"Es ist notwendig, vor dem Abstellen eines heißen Motors diesen noch zwei bis drei Minuten mit niedriger Drehzahl im Leerlauf laufen zu lassen, damit das zirkulierende Öl und Kühlwasser die gespeicherte Wärme von den Massen des Motors abführen können."},{"t":"p","text":"Wird dies nicht beachtet, so tritt nach Abstellen des Motors infolge des plötzlichen Aussetzens des Kühlsystems in gewissen Motorteilen ein erheblicher Temperaturanstieg auf, der bei Wiederholungen schädliche Folgen haben kann."},{"t":"h2","text":"Winterbetrieb"},{"t":"p","text":"Frosttemperatur läßt Motor- und Getriebeöl je nach Kältegraden mehr oder weniger zähflüssig werden, was das Anlassen des Motors und die Betätigung der Getriebeschalthebel erschwert."},{"t":"p","text":"Deshalb bei Schleppern mit Agriomatic-Getriebe nach dem Anlassen bei angezogener Handbremse und eingerücktem Gang den Agriomatic-Schalthebel Bild 8 nur so weit nach vorn in Richtung Ackergruppe drücken, bis das Lamellenpaket zum Durchrutschen kommt. Durch die hierbei erzeugte Reibungswärme wird das Getriebeöl in kurzer Zeit dünnflüssig."},{"t":"p","text":"Bei Schleppern mit Wandlergetriebe muß der Wandlerschaltgriff auf Stellung (2) Bild 7 nach hinten geschaltet werden. Den Schaltgriff nicht nach vorn auf Stellung (1) schalten, solange noch die Öldruckkontrollampe für Wandlergetriebe brennt."},{"t":"p","text":"Darauf achten, daß die Batterie immer gut geladen ist, um den erforderlichen Energieaufwand beim Starten aufbringen zu können."},{"t":"p","text":"Auf gute metallische Verbindungen der elektrischen Anschlußklemmen achten. Beim Starten genügend lange vorglühen."},{"t":"h2","text":"Frostschutz für Motorkühlwasser"},{"t":"p","text":"Um im Winterbetrieb ein Einfrieren des Kühlwassers zu verhindern, dem Kühlwasser ein Markenfrostschutzmittel in dem vom Hersteller vorgeschriebenen Mischungsverhältnis beigeben."},{"t":"p","text":"Auch die Hinterradreifen sind frostgefährdet, wenn sie eine Wasserfüllung haben."},{"t":"h2","text":"Fahrersitz"},{"t":"p","text":"Der Schlepper kann mit Standardsitz oder mit Sitz in \"De Luxe\" - Ausführung geliefert werden."},{"t":"p","text":"Beide Sitze sind mittels Gleitschienen der Größe des Fahrers entsprechend verstellbar. Zur Einstellung des Sitzes den an seiner rechten Seite liegenden Sperrhebel nach oben ziehen, Bild 10, und den Sitz nach vorn, bzw. nach hinten bewegen, so daß alle Bedienungshebel bequem vom Fahrer erreicht werden können."},{"t":"fig","label":"Bild 10","caption":"Verstellen des Fahrersitzes in seiner Entfernung zum Lenkrad","legend":[],"src":"ba/fig/p14-1.jpg","w":627,"h":483},{"t":"p","text":"Mit dem Handgriff (1) Bild 11 hinter der Rückenlehne der \"De Luxe\"-Ausführung kann die Federung entsprechend dem Gewicht des Fahrers eingestellt werden."}]},{"id":"p15","printed":"14","ratio":1.5399,"blocks":[{"t":"fig","label":"Bild 11","caption":"Verstellbare Sitzfederung","legend":["1 - Handgriff","2 - Werkzeugkasten"],"src":"ba/fig/p15-1.jpg","w":681,"h":501},{"t":"p","text":"Auf dem linken Hinterradschutzblech befindet sich ein Beifahrersitz. Auf Wunsch kann ein zweiter Beifahrersitz auf dem rechten Hinterradschutzblech angebracht werden."},{"t":"h3","text":"Radgewichte"},{"t":"p","text":"Für besondere Einsatzverhältnisse kann der Schlepper mit Vorder- und Hinterradgewichten ausgerüstet werden, um die Zugkraft zu erhöhen."},{"t":"p","text":"Darüber hinaus ist ein Füllen der Hinterreifen mit Wasser möglich."},{"t":"h2","text":"Wasserfüllen der Hinterradreifen"},{"t":"p","text":"Zum Füllen der Schlepperreifen mit Wasser und zum Entleeren wird das kombinierte Wasserfüll- und Ablaßventil empfohlen. Es ist über den IH-Ersatzteildienst erhältlich."},{"t":"fig","label":"Bild 12","caption":"Kombiniertes Wasserfüll- und Ablaßventil","legend":[],"src":"ba/fig/p15-2.jpg","w":416,"h":389},{"t":"h3","text":"Füllen"},{"t":"p","text":"Schlepper aufbocken, Ventileinsatz aus dem Schlauchventil herausnehmen und Druckluft entweichen lassen."},{"t":"p","text":"Combi-Ventil auf das Schlauchventil aufschrauben. Schlepperrad mit dem Ventil so drehen, wie es Bild 13 darstellt."},{"t":"fig","label":"Bild 13","caption":"Füllen des Hinterradreifens mit Wasser","legend":["W = Wasser","L = Luft"],"src":"ba/fig/p15-3.jpg","w":424,"h":432},{"t":"p","text":"Wasserschlauch anschließen und Wasser einlassen, bis bei L1 Wasser austritt. Der Reifen ist dann bis zu 3/4 mit Wasser gefüllt. Eine höhere Füllung ist nicht zulässig."},{"t":"p","text":"Schlepperrad mit dem Schlauchventil senkrecht nach oben drehen, Combi-Ventil abschrauben und Ventileinsatz einschrauben."},{"t":"p","text":"Reifen nach Vorschrift mit Druckluft füllen."},{"t":"h3","text":"Entleeren"},{"t":"p","text":"Schlepper aufbocken. Rad mit dem Ventil nach unten drehen. Ventileinsatz aus dem Schlauchventil herausschrauben und Wasser auslaufen lassen."},{"t":"p","text":"Combi-Ventil auf das Schlauchventil aufschrauben. Druckluftschlauch anschließen und Luft einpumpen."},{"t":"p","text":"Das Wasser entweicht bis auf einen geringen Rest. Danach tritt Luft aus, Bild 14."},{"t":"p","text":"Combi-Ventil abschrauben, Ventileinsatz in das Schlauchventil einschrauben und den Reifen nach Vorschrift mit Druckluft füllen."}]},{"id":"p16","printed":"15","ratio":1.4824,"blocks":[{"t":"fig","label":"Bild 14","caption":"Entleeren des Hinterradreifens","legend":["W = Wasser","L = Luft"],"src":"ba/fig/p16-1.jpg","w":391,"h":383},{"t":"h2","text":"Frostschutz"},{"t":"p","text":"Das Einfrieren der Wasserfüllung würde den Reifen zerstören. Bei Frostgefahr deshalb das Wasser ablassen oder ein Frostschutzmittel verwenden."},{"t":"p","text":"Hierfür eignet sich Chlorkalzium oder Chlormagnesium, welches jeweils in dem einzufüllenden Wasser aufgelöst wird."},{"t":"p","text":"Von den Reifenherstellern werden Mischungstabellen herausgegeben."},{"t":"p","text":"**Achtung:** Als Frostschutzmittel für den Motorkühler sind diese Lösungen unbrauchbar."}]},{"id":"p17","printed":"16","ratio":1.5337,"blocks":[{"t":"h1","text":"Unfallverhütung"},{"t":"list","ordered":true,"items":["Umsicht bei der Benutzung des Schleppers ist die beste Sicherung gegen Unfälle.","Beim Befahren öffentlicher Straßen ist genaue Kenntnis der Straßenverkehrsordnung Bedingung. Der Fahrer muß im Besitz des gültigen Führerscheines sein.","Der Fahrer ist auch verantwortlich für die Sicherheit des Bedienungspersonals an Anhängergeräten und der Begleiter auf Anhängewagen.","Personen dürfen auf Zug- und Anhängevorrichtungen nicht mitfahren.","Vor Betätigen der Hydraulik vergewissern, daß Beifahrer oder andere Personen nicht durch Hubgestänge oder Anbaugerät gefährdet sind.","Bei Anhängegeräten, die mit Zapfwelle betrieben werden, Schutzvorrichtungen sorgfältig anbringen. Bei Nichtbenutzung der Zapfwelle stets Schutzkappe anbringen.","Es ist verboten, während der Fahrt ab- und aufzuspringen.","Kraftstoff nur bei abgestelltem Motor auffüllen.","Kraftstoff ist feuergefährlich. Nie in der Nähe rauchen oder offenes Licht benutzen!","Die polizeilichen Vorschriften für die Verwendung von Verbrennungskraftmaschinen in Gebäuden oder in deren Nähe beachten.","Beim Verlassen der Maschine Handbremse anziehen und Gangschalthebel stets auf Neutralstellung bringen.","Vor dem Anlassen des Motors feststellen, ob der Gangschalthebel in Neutralstellung steht.","Vor dem Öffnen des Kühlerverschlusses Motor etwas abkühlen lassen, um Verbrennungen durch ausströmenden Wasserdampf zu vermeiden.","Die Lenkbremsen dürfen bei Straßenfahrt nicht benutzt werden. Die Feststellasche (9) Bild 4 muß den rechten und den linken Fußbremshebel verbinden.","Bei Straßenglätte Vorsicht beim Bremsen und nicht mit großer Geschwindigkeit fahren.","Bei Talfahrt mit angehängter, schwerer Last rechtzeitig auf kleinen Gang zurückschalten.","Bremsanlage und Beleuchtung gewissenhaft in Ordnung halten.","Zwei- und mehrachsige Lastanhänger müssen eine den Verkehrsvorschriften entsprechende Bremseinrichtung haben.","Die meisten Unfälle sind auf Unachtsamkeit zurückzuführen und können vermieden werden."]}]},{"id":"p18","printed":"17","ratio":1.5102,"blocks":[{"t":"h1","text":"Zapfwelle, Zugvorrichtungen mit Regelhydraulik"},{"t":"h2","text":"Zapfwelle"},{"t":"h3","text":"Schlepper mit Gruppengetriebe und Einfachkupplung"},{"t":"p","text":"Die Zapfwelle hat eine Nenndrehzahl von 577 U/min. Um die Zapfwelle einzuschalten, die Kupplung treten und den Zapfwellenschalthebel (1) Bild 15a nach oben ziehen. Beim Zurücklassen der Fußkupplung läuft die Zapfwelle an."},{"t":"p","text":"Soll der Schlepper gleichzeitig angefahren werden, so muß ein entsprechender Getriebegang eingerückt sein."},{"t":"p","text":"Soll die Zapfwelle bei stehendem Schlepper laufen, muß der Getriebeschalthebel in Neutralstellung sein."},{"t":"p","text":"Bei Arbeiten mit zapfwellengetriebenen Geräten stets darauf achten, daß die Kraftübertragungswelle vorschriftsmäßig durch Schutzschilder abgedeckt ist."},{"t":"p","text":"Wird die Zapfwelle nicht gebraucht, so muß der vorstehende Zapfwellenstummel durch eine Schutzkappe abgedeckt werden (1) Bild 15."},{"t":"fig","label":"Bild 15","caption":"","legend":["1 - Zapfwelle abgedeckt","2 - Zapfwellenschutzschild","3 - Hinterer Getriebeölablaßstopfen"],"src":"ba/fig/p18-1.jpg","w":623,"h":465},{"t":"h3","text":"Schlepper mit Gruppengetriebe und Zweifachkupplung"},{"t":"p","text":"Bei Ausrüstung mit Zweifachkupplung ist die Zapfwelle völlig unabhängig und kann nach Bedarf auch während der Fahrt dazu- oder abgeschaltet werden."},{"t":"p","text":"Sie läuft auch dann weiter, wenn der Schlepper mit der Fußkupplung angehalten wird."},{"t":"p","text":"Den Schalthebel für Zapfwellenkupplung (2) Bild 15a nur zum Einschalten der Zapfwelle oder zu einem kurzfristigen Auskuppeln bei einem Wendevorgang oder dergl. verwenden. Hierzu den Kupplungshebel zum Fahrersitz hin bis zum Einrasten ziehen."},{"t":"p","text":"Nachdem die Zapfwelle mittels Zapfwellenschalthebel (1) eingerückt wurde, die Handkupplung (2) langsam zurücklassen. Auf keinen Fall mit der ausgerückten Handkupplung längere Zeit fahren, weil dies zu Schäden an den Kupplungsausrückteilen führen könnte."},{"t":"p","text":"Nenndrehzahl der Zapfwelle 542 U/min."},{"t":"fig","label":"Bild 15a","caption":"","legend":["1 - Zapfwellenschalthebel","2 - Schalthebel für Zapfwellenkupplung"],"src":"ba/fig/p18-2.jpg","w":616,"h":465},{"t":"h3","text":"Schlepper mit Agriomatic-Getriebe"},{"t":"p","text":"Die Zapfwelle hat eine Nenndrehzahl von 577 U/min. Sie ist abhängig von der Motorkupplung, läuft jedoch weiter, wenn der Schlepper mittels Agriomatic-Hebel angehalten wird."},{"t":"h3","text":"Schalten der Zapfwelle bei Anhängegeräten und Maschinen mit Zapfwellenantrieb. Die Zapfwelle soll bei stehendem Schlepper laufen."},{"t":"p","text":"Agriomatic-Hebel in mittlere Stellung bringen, (1) Bild 8."},{"t":"p","text":"Fußkupplung ausrücken."},{"t":"p","text":"Zapfwellenschalthebel (1) Bild 15a einschalten."},{"t":"p","text":"Fußkupplung langsam einrücken."},{"t":"p","text":"Ist kein Gang eingeschaltet, so kann der Agriomatic-Hebel beliebig stehen. Bei eingerücktem Gang darf er nur in Mittelstellung stehen."},{"t":"h3","text":"Anfahren des Schleppers bei laufender Zapfwelle"},{"t":"p","text":"Agriomatic-Hebel in Mittelstellung bringen. Den gewünschten Gang mit dem Getriebeschalthebel schalten. Agriomatic-Hebel langsam in die vordere Stellung (Ackergruppe) drücken (2) Bild 8. Die Fußkupplung wird hierbei nicht benötigt."},{"t":"h3","text":"Gangwechsel, ohne daß die Zapfwelle stillsteht"},{"t":"p","text":"Agriomatic-Hebel in Mittelstellung bringen."},{"t":"p","text":"Der Schlepper steht nun, wenn er zugbelastet ist. Die Zapfwelle läuft weiter. Den gewünschten Gang schalten. Agriomatic-Hebel langsam in vordere Stellung bringen."},{"t":"h3","text":"Vorübergehende kurze Verlangsamung der Fahrgeschwindigkeit, aber Beibehalten der vollen Zapfwellendrehzahl, wie dies besonders bei Mähdreschern usw. erforderlich wird."}]},{"id":"p19","printed":"18","ratio":1.437,"blocks":[{"t":"p","text":"Agriomatic-Hebel in Richtung Mittelstellung (1) Bild 8 bringen, bis die Lamellenkupplung gelöst wird. Dadurch gleitet sie und die gewünschte Verlangsamung wird erreicht. Wird der Agriomatic-Hebel bis zur Mittelstellung bewegt, ist die Fahrt unterbrochen."},{"t":"p","text":"Die Zapfwelle läuft in jedem Falle mit voller Drehzahl weiter. Um weiterzufahren, Agriomatic-Hebel in vordere Stellung (2) Bild 8 bringen."},{"t":"p","text":"Eine Verlangsamung der Fahrt, wie beschrieben, soll nicht übermäßig lange ausgedehnt und nur in zwingenden Fällen angewendet werden."},{"t":"h2","text":"Vordere Anhängerkupplung"},{"t":"p","text":"Zum Rangieren von Lastanhängern ist die vordere Anhängerkupplung sehr vorteilhaft. Der Vorsteckbolzen der hinteren Anhängerkupplung paßt auch in die Bohrung der vorderen."},{"t":"h2","text":"Hintere Anhängerkupplung"},{"t":"p","text":"Die Kupplung eignet sich für schweren Zug, besonders für Lastanhänger. Der Kupplungsbolzen (1) Bild 16 ist durch eine Sperrklinke (2) gesichert. Um den Bolzen zu entfernen, den Klinkhebel nach oben ziehen."},{"t":"fig","label":"Bild 16","caption":"Hintere Anhängerkupplung","legend":["1 - Kupplungsbolzen","2 - Sperrklinke","3 - Steckbolzen","4 - Ablaßstopfen für Hydrauliköl"],"src":"ba/fig/p19-1.jpg","w":590,"h":446},{"t":"p","text":"Beim Wiedereinsetzen des Kupplungsbolzens schließt sich die Sperrklinke selbsttätig."},{"t":"p","text":"Diese Anhängerkupplung ist mittels zweier Steckbolzen (3) am Anschlußbock angebracht."},{"t":"p","text":"Werden Geräte an der Dreipunktaufhängung angebracht, so muß die Anhängerkupplung durch Entfernen der Steckbolzen abgenommen werden, um den oberen Lenker einhängen zu können."},{"t":"h2","text":"Geräteschiene für Dreipunktaufhängung"},{"t":"p","text":"Beim Anschließen von Maschinen an die Geräteschiene der Dreipunktaufhängung folgendermaßen verfahren:"},{"t":"p","text":"Hubstangen aus den Lastarmen aushängen und an den Haltebügeln (1) Bild 17 anbringen. Die Geräteschiene hat dann den normalen Abstand vom Boden."},{"t":"p","text":"Untere Lenker mit den Seitenstreben (3) starrstellen."},{"t":"fig","label":"Bild 17","caption":"Geräteschiene für Zug starrgestellt","legend":["1 - Haltebügel","2 - Hubstangen","3 - Seitenstreben","4 - Geräteschiene","5 - Lastarme"],"src":"ba/fig/p19-2.jpg","w":634,"h":452},{"t":"h2","text":"Schwenkbare Gerätezugstange"},{"t":"p","text":"Diese dient zum Anhängen von zapfwellengetriebenen Geräten und Maschinen. Dabei ergibt sich der Normalabstand vom Zapfwellenende zum Anhängepunkt. Die Zugstange läßt sich auf dem Zugrahmen, falls erforderlich, durch Steckbolzen mit Klammer starrstellen."},{"t":"p","text":"Für gewisse Arbeiten, wie z. B. zum Eggen, ist es vorteilhaft, wenn die Gerätezugstange frei schwingen kann. Zu diesem Zweck die Dreipunktaufhängung ganz anheben und den oberen Lenker abnehmen oder nach oben in der dafür vorgesehenen Halterung festsetzen."},{"t":"h2","text":"Dreipunktaufhängung"},{"t":"p","text":"Die Dreipunktaufhängung ist das Bindeglied zwischen Regelhydraulik und Anbaugerät. Die Vorteile der Regelhydraulik kommen durch die Dreipunktaufhängung zu voller Wirksamkeit, besonders bei allen Geräten, die im Boden arbeiten."},{"t":"p","text":"Die Dreipunktaufhängung des Schleppers ermöglicht die Verwendung von zapfwellengetriebenen Anbaugeräten der Kategorie I."}]},{"id":"p20","printed":"19","ratio":1.502,"blocks":[{"t":"fig","label":"Bild 18","caption":"","legend":["1 - Zapfwelle, abgedeckt","2 - Zapfwellenschutzschild","3 - Hinterer Getriebeölablaßstopfen","4 - Einstellkurbel für rechte Hubstange","5 - Oberer Lenker","6 - Untere Lenker"],"src":"ba/fig/p20-1.jpg","w":572,"h":436},{"t":"p","text":"Die Schmiernippel der Hubstangen sowie die Gelenkkugeln der unteren Lenker (6) Bild 18 von Zeit zu Zeit mit Mehrzweckfett abschmieren."},{"t":"h2","text":"Regelhydraulik"},{"t":"p","text":"Beim Anbau der Dreipunktaufhängung an die Regelhydraulik die Länge der Führungsketten so einstellen, daß die unteren Lenker nicht die Hinterradreifen berühren können."},{"t":"p","text":"Ist mit dem Tiefeneinstellhebel (2) Bild 19 die Anlage mit eingefügter Geräteschiene ganz angehoben, müssen die Führungsketten fast stramm werden. Dies richtet sich nach dem Hubbereich der unteren Lenker."},{"t":"p","text":"Um die unteren Lenker so einzuregulieren, daß ihr Hub der Kettenlänge entspricht, die Hubstangenlänge entsprechend einstellen."},{"t":"p","text":"Die Tiefe der Pflugfurche wird nicht mit dem oberen Lenker, sondern mit dem Tiefeneinstellhebel eingestellt. Der obere Lenker hat nur den Zweck, das Gerät parallel zur Furchensohle zu führen (d. h. vorderer und hinterer Pflugkörper müssen gleich tief gehen) und die Regelkraft zu übertragen. Die Länge des oberen Lenkers bei einmal erreichter paralleler Stellung des Pfluges zur Furchensohle darf auch bei Tiefenänderungen der Furche nicht mehr geändert werden. Nur bei extremen Abweichungen bei Saatpflügen und Schälen können geringfügige Änderungen erforderlich werden."},{"t":"p","text":"Die Kontermutter bei fertigeingestelltem oberen Lenker fest gegen das Spannschloß schrauben, damit sich die Länge nicht selbsttätig verstellen kann."},{"t":"fig","label":"Bild 19","caption":"","legend":["1 - Lageneinstellhebel","2 - Tiefeneinstellhebel","3 - Markierungshebel","4 - Regelhebel für Absenkgeschwindigkeit","5 - Ansaugfilter","6 - Regelfühlstift","7 - Ölmeßstab und Belüftungsfilter","8 - Ölablaßstopfen","9 - Regelgeberschwinge","10 - Saugleitung","11 - Druckleitung"],"src":"ba/fig/p20-2.jpg","w":638,"h":673},{"t":"p","text":"Bei Geräten, die keiner Tiefenregelung bedürfen und bei denen der obere Lenker somit nur zum Ankoppeln, bzw. zum Führen des Gerätes beim Anheben und Arbeiten benötigt wird, die Regelgeberschwinge durch Einfügen eines zweiten Steckbolzens in die Bohrung (4) Bild 24 starrstellen."},{"t":"p","text":"Bei Scheibengeräten sollen die Lenker eine möglichst parallele Stellung einnehmen, um den größtmöglichen Druck zum Eindringen in den Boden zu erreichen."},{"t":"p","text":"Die Regelhydraulik ist mit einem Sperrblock versehen, welcher bei stillstehendem Motor unbeabsichtigtes Absenken verhindert. Es ist jedoch erforderlich, daß vor Anlassen des Motors die Hebel (1 und 2) Bild 20 nicht in Absenkstellung stehen, da sich dann das Gerät sofort unbeabsichtigt absenkt. Aus diesem Grunde ist es geboten, stets vor Stillsetzen des Motors die mit der Hydraulik gehobenen Geräte oder Lasten abzusenken."},{"t":"p","text":"Niemals die Verschraubungen der Druckleitung lösen oder anziehen, wenn die Anlage unter Druck steht!"},{"t":"p","text":"Personen dürfen sich niemals bei laufendem Motor auf die unteren Lenker oder Geräteanschlüsse stellen."}]},{"id":"p21","printed":"20","ratio":1.4881,"blocks":[{"t":"p","text":"Die Regelhydraulik ist mit einem Abschaltsicherheitsventil ausgerüstet, das bei Überlastung automatisch anspricht und den Hubvorgang unterbricht, indem der Druck abgeschaltet wird. In einem solchen Fall die Last verringern und den Steuergeräthebel leicht nach vorn drücken. Dann den Hubvorgang mit dem Steuergeräthebel neu einleiten."},{"t":"fig","label":"Bild 20","caption":"Bedienungshebel für Regelhydraulik","legend":["1 - Lageneinstellhebel","2 - Tiefeneinstellhebel","3 - Markierungshebel"],"src":"ba/fig/p21-1.jpg","w":610,"h":469},{"t":"h2","text":"Arbeitseinsatz"},{"t":"h2","text":"Im Boden arbeitende Geräte"},{"t":"p","text":"(Pflüge, Grubber und dergl.)"},{"t":"h3","text":"Gerät absenken:"},{"t":"p","text":"Lageneinstellhebel (1) Bild 19 ganz nach unten schieben; das ist zugleich Schwimmstellung."},{"t":"h3","text":"Tiefgang, wie erforderlich, einstellen:"},{"t":"p","text":"Tiefeneinstellhebel (2) entsprechend weit nach unten schieben und Markierungshebel (3) heranstellen."},{"t":"p","text":"Während der Arbeit regelt sich der Tiefgang selbsttätig mittels der Regelgeberschwinge (9). Es ist aber jederzeit möglich, die Arbeitstiefe durch den Tiefeneinstellhebel zu ändern. Nach unten tiefer, nach oben flacher."},{"t":"p","text":"Der Markierungshebel ermöglicht eine gleichbleibende Tiefeneinstellung."},{"t":"h3","text":"Gerät anheben:"},{"t":"p","text":"Tiefeneinstellhebel (2) ganz nach oben ziehen. Der Lageneinstellhebel (1) bleibt hierbei unberührt."},{"t":"h2","text":"Uber dem Boden arbeitende Geräte"},{"t":"h3","text":"Gerät absenken:"},{"t":"p","text":"Tiefeneinstellhebel (2) ganz nach unter stellen. Lageneinstellhebel (1) so weit nach unten schieben, bis das Gerät die richtige Arbeitslage hat."},{"t":"h3","text":"Gerät ausheben:"},{"t":"p","text":"Lageneinstellhebel (1) ganz nach oben ziehen. Der Tiefeneinstellhebel bleibt unberührt."},{"t":"h3","text":"Absenkgeschwindigkeit"},{"t":"p","text":"Je nach Erfordernis kann die Absenkgeschwindigkeit geregelt werden. Hierzu dient die Absenkdrossel (4). Je weiter der Drosselhebel nach rechts gedreht wird, um so mehr wird das Absenken beschleunigt."},{"t":"p","text":"Sollte unter extremen Bodenverhältnissen und bei geringem Tiefgang des Pfluges (Schälen) unruhiges Regeln eintreten, so läßt sich dieses durch teilweises Linksdrehen des Drosselhebels beheben."},{"t":"h2","text":"Anbau von Pflügen"},{"t":"p","text":"Anbaupflüge, deren Anbaupunkte nicht schon für die Regelhydraulik eingerichtet sind, müssen nach den Richtlinien der Pflughersteller geändert werden."},{"t":"fig","label":"Bild 21","caption":"Für Regelhydraulik geeigneter Pflug mit hochgestellten Anschlußpunkten für untere Lenker","legend":[],"src":"ba/fig/p21-2.jpg","w":641,"h":494}]},{"id":"p22","printed":"21","ratio":1.4823,"blocks":[{"t":"fig","label":"Bild 22","caption":"","legend":[],"src":"ba/fig/p22-1.jpg","w":602,"h":530},{"t":"p","text":"Von dem anzubauenden Pflug muß die Schleifsohle entfernt werden. Auch das Stützrad muß abgenommen werden. Zum Schälen jedoch empfiehlt es sich, diese Teile nicht abzunehmen. Der Anschlußpunkt am Pflug für den oberen Lenker muß von den Pfluganschlußpunkten für die unteren Lenker einen Abstand von mindestens 460 mm und höchstens 560 mm haben, Bild 23. Trifft dies nicht zu, so müssen die Anschlußpunkte am Pflug entsprechend verlegt werden."},{"t":"p","text":"Die Anschlußpunkte an den unteren Lenkern sollen einen Abstand zur Scharspitze von 500 - 600 mm haben."},{"t":"p","text":"Empfohlene Maße:"},{"t":"table","caption":"","head":[],"rows":[["für einscharigen Pflug","500 mm"],["für zweischarigen Pflug","550 mm"],["für dreischarigen Pflug","600 mm"]]},{"t":"p","text":"Sollten hierbei im oberen Lenker bei der Arbeit weder Zug- noch Druckkraft vorhanden sein und sollte dieser lose hängen, so müssen die Anschlußpunkte für die unteren Lenker am Pflug noch weiter nach oben verlegt werden, Bilder 21 und 22, wobei das Maß zum oberen Koppelpunkt 460 mm jedoch nicht unterschreiten soll; siehe Bild 23. Anzustreben ist hier ein Maß von 550 mm."},{"t":"fig","label":"Bild 23","caption":"","legend":[],"src":"ba/fig/p22-2.jpg","w":612,"h":464},{"t":"p","text":"Wichtig für das schnelle Eindringen des Pfluges in schweren Boden ist, vor Beginn der Pflugarbeit am Vorgewende eine Querfurche zu ziehen."},{"t":"p","text":"Die Regelgeberschwinge (1) Bild 24 hat zwei Bohrungen für den Anschluß des oberen Lenkers. Dadurch kann die Empfindlichkeit der Regelhydraulik eingestellt werden. Wird der obere Lenker in der oberen Bohrung befestigt, so ist die Anlage am empfindlichsten und reagiert auf die geringsten Impulse. Die untere Bohrung ist für eine weniger empfindliche Einstellung."},{"t":"fig","label":"Bild 24","caption":"","legend":["1 - Regelgeberschwinge","2 - Regelfühlstift","3 - Oberer Lenker","4 - Bohrung zum Starrstellen der Regelgeberschwinge","5 - Drehbolzen für Regelgeberschwinge"],"src":"ba/fig/p22-3.jpg","w":619,"h":453},{"t":"p","text":"Es empfiehlt sich, den oberen Lenker zunächst stets in der unteren Bohrung zu befestigen und in dieser Lage die Arbeit zu beginnen. Sind in dieser Lage die Regelimpulse am oberen Lenker nicht stark genug, so muß er in der oberen Bohrung befestigt werden."},{"t":"p","text":"Wenn der Regelbereich der Ausgleichfeder nicht mehr ausreicht, d. h., wenn sie in ihrem ganzen Wirkungsbereich durch den Geber (1) zusammengedrückt oder ausgezogen ist, muß der obere Lenker an der unteren Bohrung angebracht werden. Reicht diese Maßnahme nicht aus, den Drehpunktbolzen (5) der Regelgeberschwinge in die obere Bohrung (4) versetzen."},{"t":"h2","text":"Blocksteuergeräte und Abreißkupplungen"},{"t":"p","text":"Zur hydraulischen Betätigung von Zusatzausrüstungen, wie Frontlader, Mähwerk und anderen Geräten mit eigenem Arbeitszylinder sind Blocksteuergeräte, Bild 25 vorgesehen. Der hydraulische Anschluß der Geräte erfolgt ohne Werkzeug über Abreißkupplungen. Mit jedem Steuergerät können zwei Geräte wechselseitig betätigt werden, wobei die Verbindung zu dem ungebrauchten Gerät an der Abreißkupplung getrennt werden muß. Es können nach Bedarf 1-3 Blocksteuergeräte angeschraubt werden."}]},{"id":"p23","printed":"22","ratio":1.4994,"blocks":[{"t":"fig","label":"Bild 25","caption":"","legend":["1 - Blocksteuergeräthebel","2 - Feststellbüchse"],"src":"ba/fig/p23-1.jpg","w":616,"h":479},{"t":"p","text":"Während der Arbeit alle Steuergeräthebel (1) Bild 25 für die Zusatzausrüstungen, die nicht verwendet werden, durch Hineindrücken der Feststellbüchse (2) gegen unbeabsichtigtes Betätigen sichern."}]},{"id":"p24","printed":"23","ratio":1.5018,"blocks":[{"t":"h1","text":"Wartung und Pflege"},{"t":"table","caption":"Regelmäßige Wartungs- und Pflegearbeiten","head":["Regelmäßige Wartungs- und Pflegearbeiten","Nr. im Schmierplan"],"rows":[["**Nach jeweils 10 Betriebsstunden**",""],["Motorölstand kontrollieren, Seite 31","4"],["Kühlwasserstand kontrollieren, Seite 32",""],["**Nach jeweils 50 Betriebsstunden**",""],["Schlepper abschmieren, Seite 38","17-24, 27, 28"],["Luftfilter - Vorabscheider säubern, Seite 27","1"],["**Nach jeweils 200 Betriebsstunden**",""],["Ölbadluftfilter, Öl wechseln und reinigen, Seite 26","1"],["Motorölwechsel, Seite 31","2, 3"],["Motorölfilter auswechseln, Seite 32","5"],["Einspritzpumpe, Ölstand prüfen und nachfüllen, Seite 28","6"],["Getriebeölstand kontrollieren, Seite 36","9"],["Filter für Wandlergetriebe reinigen, Seite 36","10"],["Ansaugfilter für Wandlergetriebe reinigen, Seite 36","12"],["Lenkgetriebe, Ölstand prüfen und nachfüllen, Seite 38","11"],["Hydraulikölstand kontrollieren, Seite 38","13"],["Kupplung und Bremsen prüfen und nachstellen, Seite 39, 40, 41",""],["Batterie, Säurestand prüfen, Seite 45",""],["Keilriemenspannung prüfen, Seite 34",""],["**Nach jeweils 800 Betriebsstunden**",""],["Hydraulikölwechsel, Seite 37","13, 14"],["Hydraulikölansaugfilter reinigen, Seite 37","15"],["Schlepper abschmieren","25, 26"],["Kraftstoffilterelement auswechseln, Seite 29","16"],["**Nach jeweils 1600 Betriebsstunden**",""],["Getriebeöl wechseln, Seite 35","7, 8"],["Vorderradnaben reinigen, schmieren und neu einstellen, Seite 42","29"],["Alle Schraubverbindungen nachziehen",""],["Einspritzpumpe, Ölwechsel, Seite 29","6"]]}]},{"id":"p25","printed":"24","ratio":1.502,"blocks":[{"t":"h2","text":"Schmierplan"},{"t":"fig","label":"","caption":"","legend":[],"src":"ba/fig/p25-1.jpg","w":1100,"h":614},{"t":"table","caption":"Zu verwendende Schmiermittel","head":["Zu verwendende Schmiermittel",""],"rows":[["Motoröl","SAE 20, HD 4,1 Liter"],["Luftfilter","Motoröl, 0,35 Liter"],["Getriebeöl","SAE 80 ohne Additive, 34 Liter"],["Lenkgetriebe","SAE 90 Hypoidöl, nach Bedarf"],["Hydrauliköl","IH-Hydrauliköl, 12,8 Liter"],["Schmierfett","Mehrzweckfett, nach Bedarf"]]},{"t":"p","text":"Nähere Auskünfte über die empfohlenen Markenschmiermittel erteilen auf Wunsch die zuständigen IH-Händler."},{"t":"p","text":"Alle Schmieranweisungen beziehen sich auf die vorstehend empfohlenen Schmiermittel-Qualitäten."},{"t":"p","text":"Werden Schmiermittel verwendet, die nicht diesen Spezifikationen entsprechen, können Folgeschäden auftreten, für die wir auch innerhalb der Garantiezeit keine Gewähr leisten."},{"t":"note","text":"Änderungen vorbehalten!"}]},{"id":"p26","printed":"25","ratio":1.5337,"blocks":[{"t":"h2","text":"Erläuterungen zum Schmierplan"},{"t":"table","caption":"Erläuterungen zum Schmierplan (Anmerkung der Digitalisierung: Spalten 10–1600 = nach Betriebsstunden; im Original zusammengefasste Zellen der Spalte „Lage“ sind hier je Zeile wiederholt.)","head":["Nr. im Plan","Beschreibung","Lage","10","50","200","800","1600"],"rows":[["1","Ölbadluftfilter reinigen und Öl wechseln (bei staubiger Arbeit)","vorn","(x)","","x","",""],["","Luftfilter-Vorabscheider reinigen","vorn","","x","","",""],["2","Motoröleinfüllstopfen, Öl wechseln","links","","","x","",""],["3","Motorölablaßschraube, Öl wechseln","Mitte","","","x","",""],["4","Motorölmeßstab, Ölstand prüfen","rechts","x","","","",""],["5","Motorölfilter auswechseln","rechts","","","x","",""],["6","Einspritzpumpe, Ölstand prüfen und auffüllen","links","","","x","",""],["7","Getriebeölablaßstopfen, vorn – Ölwechsel","Mitte u. rechts","","","","","x"],["","Getriebeölablaßstopfen, hinten – Ölwechsel","Mitte","","","","","x"],["8","Getriebeöleinfüllstopfen, Öl wechseln","Mitte","","","","","x"],["9","Getriebeölkontrollschraube, Ölstand prüfen","links","","","x","",""],["10","Filter für Wandlergetriebe reinigen","Mitte","","","x","",""],["11","Lenkgetriebe, Ölstand prüfen und auffüllen","Mitte","","","","","x"],["12","Ansaugfilter für Wandlergetriebe reinigen","hinten","","","x","",""],["13","Hydrauliköl Einfüllstopfen und Ölmeßstab, Ölstand prüfen","Mitte","","","x","",""],["","Hydraulikölwechsel","hinten","","","","x",""],["14","Hydraulikölablaßstopfen, Ölwechsel","hinten","","","","x",""],["15","Hydraulikölansaugfilter reinigen","","","","","x",""],["16","Kraftstoffilter reinigen, Element auswechseln","","","","","x",""],["17","Vorderachslager, vorn","vorn","","x","","",""],["18","Vorderachslager, hinten","Mitte","","x","","",""],["19","Umlenkhebel","Mitte","","x","","",""],["20","Achsschenkelbolzen","links u. rechts","","x","","",""],["21","Bremspedal","rechts","","x","","",""],["22","Bremswelle","rechts","","x","","",""],["23","Differentialsperre","rechts","","x","","",""],["24","Kupplungspedal","links","","x","","",""],["25","Handhebel für Zapfwellenkupplung","links","","","","x",""],["26","Ausrücklager für Zweifachkupplung","links","","","","x",""],["27","Agriomatic- oder Gruppenschalthebel","links","","x","","",""],["28","Hubstangen und Kugeln der unteren Lenker","hinten","","x","","",""],["29","Vorderradnaben reinigen und abschmieren","","","","","","x"]]}]},{"id":"p27","printed":"26","ratio":1.5293,"blocks":[{"t":"h2","text":"Werkzeuge"},{"t":"p","text":"Die für Wartungs- und Pflegearbeiten erforderlichen Werkzeuge befinden sich in dem Werkzeugkasten (2) Bild 11."},{"t":"p","text":"Das Dreheisen für den Steckschlüssel ist hinter dem Kühlergrill untergebracht, siehe (5) Bild 36."},{"t":"h2","text":"Abnehmen der Motorhaube"},{"t":"p","text":"Der Schlepper ist so konstruiert, daß alle wesentlichen Aggregate leicht zugänglich sind. Ein Abnehmen der Motorhaube ist daher nur selten erforderlich."},{"t":"p","text":"Die Motorhaube ist beiderseitig mit je einer Kopfschraube (4) Bild 27 an der Kühlerverkleidung und durch je eine Pendelschraube mit Flügelmutter (5) an der Innenseite der Seitenverkleidung des Schleppers befestigt."},{"t":"p","text":"Sollte ein Abnehmen der Motorhaube erforderlich sein, die beiden Kopfschrauben (4) entfernen, die Flügelmuttern der Pendelschraube (5) lösen und diese aus ihren Rastschlitzen ziehen. Motorhaube abnehmen."},{"t":"p","text":"Beim Wiederanbringen in umgekehrter Reihenfolge verfahren."},{"t":"p","text":"Kühlerverkleidung (1) und Seitenbleche (2) verbleiben beim Abnehmen der Motorhaube am Schlepper."},{"t":"fig","label":"Bild 27","caption":"Abnehmen der Motorhaube","legend":["1 - Kühlerverkleidung","2 - Seitenbleche","3 - Motorhaube","4 - Bohrung für vordere Halteschraube","5 - Pendelschraube mit Flügelmutter"],"src":"ba/fig/p27-1.jpg","w":622,"h":425},{"t":"h2","text":"Abnehmen des Kühlergrills"},{"t":"p","text":"Luftfilter, Kraftstoffilter und Scheinwerfer sind vor dem Kühler angebracht. Sie sind durch Abnehmen des Kühlergrills zugänglich, Bild 28."},{"t":"fig","label":"Bild 28","caption":"Abnehmen und Einfügen des Kühlergrills","legend":["1 - Haltenasen","2 - Blechabkantung","3 - Riegelschrauben","4 - Seitliche Haken"],"src":"ba/fig/p27-2.jpg","w":610,"h":403},{"t":"p","text":"Die beiden Riegelschrauben (3) Bild 28 durch Linksdrehen lösen, bis das Kühlergrill frei wird. Dasselbe nach vorn kippen und herausheben."},{"t":"p","text":"Beim Wiedereinsetzen darauf achten, daß die Haltenasen (1) unten hinter die Blechabkantung (2) greifen. Die seitlichen Haken (4) durch leichten Druck von außen zum Eingriff bringen und die Riegelschrauben festdrehen."},{"t":"h2","text":"Ölbadluftfilter"},{"t":"p","text":"Die vom Motor angesaugte Luft muß vor Eintritt in die Zylinder gründlich gereinigt werden, denn Staub und Sand haben eine schleifende Wirkung und führen zu raschem Verschleiß der arbeitenden Motorteile."},{"t":"p","text":"Der Schlepper ist mit einem Ölbadluftfilter ausgerüstet. Das sich im Ölbehälter (2) Bild 29 befindende Öl und das untere Filterelement (3) halten alle Unreinigkeiten, die in der Ansaugluft vorhanden sind, zurück. Das obere Filterelement verschmutzt nur gering, und zwar nur dann, wenn das Öl im Behälter nicht rechtzeitig gewechselt wird."}]},{"id":"p28","printed":"27","ratio":1.4909,"blocks":[{"t":"fig","label":"Bild 29","caption":"Ölbadluftfilter: Ölbehälter abgenommen","legend":["1 - Klemmbügel","2 - Ölstandsmarkierung","3 - Unteres Filterelement","4 - Dichtring","5 - Oberes Filterelement"],"src":"ba/fig/p28-1.jpg","w":603,"h":433},{"t":"p","text":"Alle 200 Betriebsstunden, bei sehr staubigen Arbeitsbedingungen täglich, Ölbehälter mit Filterelement abnehmen. Ölbehälter entleeren und mit Dieselkraftstoff reinigen. Filterelement mit einem weichen Pinsel nur in Dieselkraftstoff auswaschen."},{"t":"fig","label":"Bild 30","caption":"Reinigen des Filterelementes","legend":["1 - Dichtring, außen","2 - Filterelement"],"src":"ba/fig/p28-2.jpg","w":533,"h":406},{"t":"p","text":"Ölbehälter bis zur vorgeschriebenen Höhe, d.h. bis zur Ölstandsmarkierung (2) Bild 29, mit Motoröl, wie es auch zur Schmierung des Motors verwendet wird, füllen. Beim Wiederanbringen darauf achten, daß der Dichtring (4) richtig sitzt und unbeschädigt ist."},{"t":"h2","text":"Luftfilter Vorabscheider"},{"t":"p","text":"Auf dem Ölbadluftfilter ist zusätzlich ein Vorabscheider angebracht, der grobe Staubteile aus der Ansaugluft ausscheidet, bevor diese in das Ölbadluftfilter gelangt."},{"t":"p","text":"Der Vorabscheider arbeitet trocken. Den Staubbehälter (3) Bild 31 nie mit Öl füllen."},{"t":"fig","label":"Bild 31","caption":"Luftfilter-Vorabscheider","legend":["1 - Fächerring","2 - Deckel","3 - Staubbehälter"],"src":"ba/fig/p28-3.jpg","w":533,"h":415},{"t":"p","text":"Alle 50 Betriebsstunden bei größerem Staubanfall jedoch täglich, den Staubbehälter vom Luftfilter abnehmen und entleeren. Zu große Schmutzanhäufung im Staubbehälter beeinträchtigt die Luftreinigung."},{"t":"h2","text":"Kraftstoff"},{"t":"p","text":"Der beste Kraftstoff ist für den Motor gerade gut genug. Gelagerte Kraftstoffe vor Verunreinigung schützen. Behälter nie offen stehen lassen. Verzinkte Behälter sind zum Aufbewahren des Kraftstoffes ungeeignet."},{"t":"p","text":"Den Kraftstoffbehälter der Maschine mit reinem Dieselkraftstoff füllen; diesen beim Einfüllen durch ein Sieb oder Leinentuch filtern, Bild 32."},{"t":"p","text":"Wurde der Kraftstoffbehälter vollständig leergefahren, das Kraftstoffsystem entlüften."}]},{"id":"p29","printed":"28","ratio":1.4693,"blocks":[{"t":"fig","label":"Bild 32","caption":"","legend":[],"src":"ba/fig/p29-1.jpg","w":539,"h":378},{"t":"h2","text":"Kraftstoffzusatzmittel"},{"t":"p","text":"Bei erschwerten Betriebsbedingungen kann dem Dieselkraftstoff das Zusatzmittel \"Autol-Desolite\" zugesetzt werden. Es hat die Aufgabe, Einspritzpumpe, Einspritzdüsen, Ventile und Verbrennungsraum vor schädlichen Ablagerungen und deren störenden Einwirkungen zu schützen."},{"t":"p","text":"Das Zusatzmittel ist im In- und Ausland erhältlich. Das Mischungsverhältnis gibt der Lieferant bekannt."},{"t":"h2","text":"Wartung der Einspritzpumpe"},{"t":"p","text":"Der Motor ist mit einer Bosch-Reiheneinspritzpumpe ausgerüstet. Sie besteht aus 3 Pumpenelementen und dem Regler. Die Kraftstoffversorgung des Einspritzsystems erfolgt durch Zufluß aus dem höher gelegenen Kraftstoffbehälter. Zusätzlich kann eine Kraftstofförderpumpe mit Handpumpe geliefert werden."},{"t":"p","text":"Alle Reparaturarbeiten an der Einspritzpumpe müssen ausschließlich dem Bosch-Dienst vorbehalten bleiben, der über die erforderlichen Spezialwerkzeuge und Apparaturen verfügt. Reparaturen von unberufener Hand können der Einspritzpumpe nur schaden."},{"t":"p","text":"Auf keinen Fall darf die Einspritzpumpe bei der Reinigung des Motors mit Druckwasser abgespritzt werden, da kleinste Spuren von Wasser, die ins Innere der Pumpe gelangen könnten, Störungen hervorrufen oder Bruch der Federn herbeiführen."},{"t":"fig","label":"Bild 33","caption":"Kraftstoffsystem","legend":["1 - Einspritzpumpe","2 - Fliehkraftverstellregler","3 - Ölstandschraube","4 - Belüftungsfilter","5 - Entlüftungsschraube","6 - Entlüftungsschraube","7 - Befestigungsschraube","8 - Kraftstoffilter","9 - Überlaufleitung","10 - Einspritzdüsenhalter","11 - Kraftstoffbehälter","12 - Kraftstoffabsperrhahn"],"src":"ba/fig/p29-2.jpg","w":587,"h":348},{"t":"p","text":"Einspritzpumpe und Regler werden durch ein gemeinsames Ölbad geschmiert. Zur Schmierung der Einspritzpumpe das gleiche Öl verwenden wie für den Motor."},{"t":"fig","label":"Bild 34","caption":"Einspritzpumpe","legend":["1 - Belüftungsfilter","2 - Ölstandkontrollschraube","3 - Entlüftungsschraube"],"src":"ba/fig/p29-3.jpg","w":496,"h":365}]},{"id":"p30","printed":"29","ratio":1.5248,"blocks":[{"t":"p","text":"Den Ölstand nach etwa 200 Betriebsstunden prüfen. Hierzu die Ölstandschraube (2) Bild 34 herausschrauben und das überflüssige Öl-Kraftstoffgemisch ablaufen lassen. Tritt kein Ölgemisch aus, das Belüftungsfilter (1) von Hand abschrauben und durch die Öffnung frisches Motoröl einfüllen, bis es an der Ölstandöffnung (2) auszufließen beginnt. Ölstandschraube wieder einschrauben und fest anziehen. Belüftungsfilter von Hand einschrauben; kein Werkzeug verwenden."},{"t":"h2","text":"Behandlung bei längeren Arbeitspausen"},{"t":"p","text":"Wird der Motor für längere Zeit (über 3 Monate) außer Betrieb gesetzt, darf der Dieselkraftstoff nicht in der Pumpe bleiben, da er mit der Zeit verharzt, wodurch die Einspritzpumpenkolben festkleben würden. Um dies zu verhindern, vor dem Stillsetzen den Kraftstoff ablassen und dafür etwas Petroleum einfüllen. Mit dieser Füllung den Motor eine Viertelstunden laufen lassen. Hierdurch wird der Dieselkraftstoff ausgewaschen und ein Verkleben der Pumpenkolben verhindert."},{"t":"h2","text":"Regler"},{"t":"p","text":"Durch den Verstellregler kann jede gewünschte Drehzahl innerhalb eines bestimmten Drehzahlbereiches mit Hilfe des Hand- oder Fußgashebels eingestellt werden. Eine selbsttätige, aus einem Fliehkraftregler bestehende Regeleinrichtung sorgt dann dafür, daß der Motor diese Drehzahl auch bei Belastungsänderung einhält."},{"t":"p","text":"Die Einstellung des Reglers für die niedrigste und höchste Drehzahl des Motors ohne Belastung ist auf 600 bis 2050 Umdrehungen pro Minute begrenzt."},{"t":"p","text":"Reparaturen und Einstellungen am Regler dürfen nur vom \"Bosch\"-Dienst vorgenommen werden."},{"t":"p","text":"Die Schmierung des Reglers erfolgt durch ein gemeinsames Ölbad mit ler Einspritzpumpe."},{"t":"h2","text":"Kraftstoffilter"},{"t":"p","text":"Das Kraftstoffilter ist vor dem Kühler neben dem Luftfilter angebracht und ist nach Abnehmen des Kühlergrills zugänglich. Es hat die Aufgabe, kleinste im Kraftstoff enthaltene Fremdkörper, die Einspritzpumpe und Düsen beschädigen könnten, von diesen fernzuhalten und auszuscheiden."},{"t":"p","text":"Das Filterelement muß normalerweise etwa alle 800 Betriebsstunden ausgewechselt werden. Sollte jedoch die Motorleistung bei Höchstbelastung nachlassen, so ist dies ein Zeichen dafür, daß das Filterelement verschmutzt ist und ausgewechselt werden muß, unabhängig von der Zahl der Betriebsstunden."},{"t":"p","text":"Beim Auswechseln des Filterelements folgendermaßen verfahren:"},{"t":"p","text":"Kühlergrill abnehmen. Kraftstoffabsperrhahn (12) Bild 33 schließen."},{"t":"fig","label":"Bild 35","caption":"","legend":["1 - Halteschraube","2 - Filterglocke"],"src":"ba/fig/p30-1.jpg","w":525,"h":407},{"t":"p","text":"Halteschraube (1) Bild 35 lösen und die Filterglocke (2) abnehmen. Das alte Filterelement wegwerfen. Die Filterglocke in Dieselkraftstoff gründlich reinigen."},{"t":"fig","label":"Bild 36","caption":"","legend":["1 - Filterglocke","2 - Filterelement","3 - Filtersockel","4 - Dichtung","5 - Dreheisen für Steckschlüssel"],"src":"ba/fig/p30-2.jpg","w":534,"h":419},{"t":"p","text":"Anschließend ein neues Filterelement (2) Bild 36 einsetzen und die Filterglocke (1) an Sockel (3) anschrauben. Dabei darauf achten, daß die Dichtung (4) zwischen Filterglocke und Sockel einwandfrei abdichtet."},{"t":"p","text":"Kraftstoffsystem nach Filterwechsel entlüften."}]},{"id":"p31","printed":"30","ratio":1.493,"blocks":[{"t":"h2","text":"Entlüften des Kraftstoffsystems"},{"t":"p","text":"Das Kraftstoffsystem darf keine Luft enthalten. Das Entlüften muß durchgeführt werden, wenn Teile des Kraftstoff- oder Einspritzsystems abgenommen waren oder wenn der Kraftstoffbehälter nicht rechtzeitig aufgetankt wurde, so daß Luft in das Kraftstoffsystem gelangen konnte."},{"t":"p","text":"Zum Entlüften folgendermaßen vorgehen:"},{"t":"p","text":"Feststellen, ob hinreichend Kraftstoff im Behälter vorhanden ist. Kraftstoffabsperrhahn (12) Bild 33 öffnen. Die Entlüftungsschraube am Deckel des Kraftstoffilters lösen und solange Kraftstoff ablaufen lassen, bis er blasenfrei ausfließt, Bild 37; dann die Schraube wieder festziehen."},{"t":"fig","label":"Bild 37","caption":"Entlüften des Kraftstoffilters","legend":[],"src":"ba/fig/p31-1.jpg","w":637,"h":473},{"t":"p","text":"Die Entlüftungsschraube (1) Bild 38 der Einspritzpumpe lösen, bis Kraftstoff blasenfrei austritt. Entlüftungsschraube festziehen."},{"t":"fig","label":"Bild 38","caption":"Entlüften der Einspritzpumpe","legend":["1 - Entlüftungsschraube","2 - Belüftungsfilter","3 - Ölstandschraube"],"src":"ba/fig/p31-2.jpg","w":635,"h":483},{"t":"p","text":"Ist eine Kraftstofförderpumpe angebaut, diese beim Lösen der Entlüftungsschrauben betätigen. Hierzu den Pumpenknopf nach links drehen und den Pumpenkolben von Hand betätigen."},{"t":"h2","text":"Einspritzleitungen"},{"t":"p","text":"Abnehmen und Wiederanbringen der Einspritzleitungen sollte nur von fachkundiger Hand vorgenommen werden."},{"t":"p","text":"Wenn aus irgendeinem Grund das Abnehmen der Einspritzleitungen nötig ist, muß es mit größter Sorgfalt geschehen. Zuvor äußerlich alle Verunreinigungen von den Verschraubungen entfernen."},{"t":"p","text":"Sobald die Leitungen abgenommen sind, diese und die Anschlußstutzen sofort mit Schutzkappen verschließen, damit kein Schmutz eindringen kann."},{"t":"p","text":"Beim Wiederanbringen der vorher sorgfältig gereinigten Leitungen darauf achten, daß sich die Leitungskegel spannungsfrei in die entsprechenden Anschlußstutzen einfügen lassen. Die Überwurfmuttern sorgfältig anziehen und dabei die Anschlußstutzen mit einem zweiten Schlüssel festhalten."},{"t":"p","text":"Die Kraftstoffschlauchleitungen dürfen nicht kurzgebogen oder geknickt montiert werden. Hierauf beim Anziehen der Hohlschrauben besonders achten. Die Leitungen müssen so verlegt werden, daß sie nicht durchscheuern können."},{"t":"h2","text":"Einspritzdüsen"},{"t":"p","text":"Jede Einspritzdüse ist mittels Überwurfmutter an ihrem Düsenhalter festgeschraubt. Die Düsenhalter lassen sich nach Abschrauben der Flanschmuttern aus dem Zylinderkopf herausziehen."},{"t":"p","text":"Die Einspritzdüse besteht aus Düsenkörper (3) Bild 39 und Düsennadel (1). Beide Teile sind aus gehärtetem, hochwertigem Stahl hergestellt und mit einer Feinpassung auf- und miteinander eingeschliffen. Nadel und Körper können daher nicht voneinander getrennt verwendet werden, sondern sind stets als eine Einheit zu betrachten und im Bedarfsfall zusammen auszuwechseln."},{"t":"p","text":"Die Pflege der Einspritzdüsen erstreckt sich nur auf vorbeugende Maßnahmen gegen vorzeitigen Verschleiß. Die Abnutzung der Düsen wird in erster Linie durch Unreinigkeiten im Kraftstoff herbeigeführt. Der Kraftstoff muß daher so gut wie irgendmöglich gereinigt werden, bevor er zur Einspritzpumpe gelangt. Solange das Kraftstoffilter einwandfrei arbeitet, ist keine Gefahr vorhanden."},{"t":"p","text":"Reinigungs- und Instandsetzungsarbeiten an den Düsen dem nächsten Bosch-Dienst überlassen."},{"t":"fig","label":"Bild 39","caption":"Einspritzdüse","legend":["1 - Düsennadel","2 - Zulaufbohrung","3 - Düsenkörper"],"src":"ba/fig/p31-3.jpg","w":176,"h":243}]},{"id":"p32","printed":"31","ratio":1.513,"blocks":[{"t":"h2","text":"Motorölwechsel"},{"t":"p","text":"Betriebssicherheit, zufriedenstellende Leistung und Lebensdauer des Motors hängen in hohem Maße von sorgfältiger Schmierung ab. Nachlässigkeit in dieser Beziehung hat ernste Betriebsstörungen, übermäßigen Verschleiß und schließlich vollständige Betriebsunfähigkeit des Schleppers zur Folge."},{"t":"p","text":"Zur Schmierung des Motors darf nur hochwertiges, mit Additiven angereichertes HD-Öl verwendet werden, wie im Schmierplan angegeben."},{"t":"p","text":"Den Ölstand täglich am Ölmeßstab (1) Bild 40 prüfen. Bei allen Ölstandsprüfungen muß der Schlepper waagerecht stehen."},{"t":"p","text":"Ist der Motorölstand bis zur unteren Kerbmarke (2) gesunken, Öl nachfüllen bis der Ölstand die obere Kerbmarke (1) erreicht."},{"t":"fig","label":"Bild 40","caption":"Prüfen des Motorölstandes","legend":["1 - Ölmeßstab, obere Kerbmarke","2 - Untere Kerbmarke","3 - Motorölfilter","4 - Öldruckschalter"],"src":"ba/fig/p32-1.jpg","w":636,"h":483},{"t":"p","text":"Bei der neuen Maschine muß der erste Ölwechsel nach 20 Betriebsstunden, dann fortlaufend nach jeweils 200 Betriebsstunden erfolgen. Das alte Öl bei warmem Motor durch Entfernen des Ölablaßstopfens an der Ölwanne Bild 41 ablassen."},{"t":"fig","label":"Bild 41","caption":"Ablassen des Motoröls","legend":[],"src":"ba/fig/p32-2.jpg","w":651,"h":499},{"t":"p","text":"Danach Ölablaßstopfen reinigen und wieder fest einschrauben."},{"t":"p","text":"Das Motoröl in den links am Motor befindlichen Einfüllstutzen einfüllen, Bild 42. Zu einer Motorfüllung werden ca. 4,1 Liter benötigt."},{"t":"fig","label":"Bild 42","caption":"Einfüllen des Motoröls","legend":[],"src":"ba/fig/p32-3.jpg","w":641,"h":473},{"t":"p","text":"Bei jedem Ölwechsel auch das Ölfilter erneuern."},{"t":"h2","text":"Erneuern des Motorölfilters"},{"t":"p","text":"Das Motoröl durchströmt bei laufendem Motor das Motorölfilter Bild 43a und läßt dabei Verunreinigungen und Rückstände auf dem Element zurück."},{"t":"fig","label":"Bild 43","caption":"Sauberes Motorölfilter / Verstopftes Motorölfilter","legend":["1 - Einströmendes Öl von der Ölpumpe","2 - Ausströmendes Öl zum Hauptschmierkanal","3 - Sicherheitsventil, geschlossen","4 - Sicherheitsventil, geöffnet"],"src":"ba/fig/p32-4.jpg","w":636,"h":454},{"t":"p","text":"Wenn nach längerer Betriebszeit das Filtermaterial nicht mehr genügend Öl durchläßt, hebt sich das Sicherheitsventil (4) Bild 43 gegen den Druck der Feder ab und läßt Öl (2) zum Hauptschmierkanal des Motors fließen. Dieses Öl ist zwar ungereinigt, aber die Ölversorgung ist nicht unterbrochen."}]},{"id":"p33","printed":"32","ratio":1.494,"blocks":[{"t":"p","text":"Ein derartig verschmutztes Filter wird nicht durch zu niedrigen Motoröldruck am Armaturenbrett angezeigt. Es ist daher wichtig, das Ölfilter bei jedem Motorölwechsel herauszuschrauben und durch ein neues zu ersetzen."},{"t":"fig","label":"Bild 43a","caption":"Lösen des Ölfilters","legend":["1 - Sockel","2 - Filterelement","3 - Mitnehmernocken"],"src":"ba/fig/p33-1.jpg","w":552,"h":392},{"t":"p","text":"Die Filterglocke und das Filterelement sind ein Teil (2) Bild 43a und in den Filtersockel (1) eingeschraubt. Sollte das Filter festsitzen, zum Lösen geeigneten Hebel verwenden. Am Boden des Filters sind zu diesem Zweck Mitnehmernocken (3) vorgesehen."},{"t":"p","text":"Den Dichtring leicht einölen und das neue Element **von Hand** festschrauben."},{"t":"p","text":"Motor laufen lassen und prüfen, ob die Verbindung dicht ist. Falls erforderlich, leicht nachziehen."},{"t":"h2","text":"Kühlsystem"},{"t":"p","text":"Zur Gewährleistung einer gleichmäßigen, günstigen Betriebstemperatur des Motors werden Zylinderkopf und Zylinderwände durch Wasser gekühlt. Das im Motor erhitzte Wasser wird im Kühler abgekühlt. Durch die Wasserpumpe, zwischen Zylinderkopf und Kühler, wird das im Motor und Kühler enthaltene Wasser in Umlauf gesetzt, fließt vom Zylinderkopf in den Kühler und aus diesem in das Kurbelgehäuse und in den Zylinderkopf zurück."},{"t":"p","text":"Wird Kühlwassermangel bei heißem Motor festgestellt, darf unter keinen Umständen sofort kaltes Wasser in den Kühler eingefüllt werden. Der Motor muß in einem solchen Fall abgestellt werden und abkühlen, ehe kaltes Wasser eingefüllt wird. Sofern heißes Wasser (80° C und mehr) zur Verfügung steht, braucht der Motor nicht erst abzukühlen."},{"t":"p","text":"Um Kühlwasser einzufüllen oder den Wasserstand zu prüfen, die Verschlußklappe (1) Bild 44 öffnen und den Druckverschluß abschrauben. Den Kühler bis ca. 5 cm unter den Rand mit sauberem Wasser füllen. Den Wasserstand täglich, bei schwerer Arbeit und bei warmem Wetter auch öfter prüfen."},{"t":"fig","label":"Bild 44","caption":"Einfüllen des Kühlwassers","legend":["1 - Verschlußklappe","2 - Druckverschluß"],"src":"ba/fig/p33-2.jpg","w":516,"h":371},{"t":"p","text":"Sauberes, kalkarmes Wasser verwenden."},{"t":"p","text":"Bei auf Frosttemperatur abgekühltem Motor das einzufüllende Kühlwasser vorher auf 50 - 70° C anwärmen."},{"t":"h2","text":"Kühlerdruckverschluß"},{"t":"fig","label":"Bild 45","caption":"","legend":["1 - Feder für Unterdruckventil","2 - Feder für Überdruckventil","3 - Überdruckventil","4 - Unterdruckventil","5 - Dampfaustritt bei Überdruck","6 - Lufteintritt bei Unterdruck","7 - Verschlußmembrane"],"src":"ba/fig/p33-3.jpg","w":549,"h":245}]},{"id":"p34","printed":"33","ratio":1.4957,"blocks":[{"t":"p","text":"Der Kühlerdruckverschluß Bild 45 hält einen gewissen konstanten Druck im Kühlsystem aufrecht. Dadurch wird der Siedepunkt des Kühlwassers heraufgesetzt und Wasserverlust durch vorzeitiges Kochen verhindert."},{"t":"p","text":"Der ganze Deckel wirkt als Überdruckventil. Ein Verstopfen oder Verklemmen kann somit nicht auftreten. Bei zu hohem Druck im Kühler hebt sich das Überdruckventil (3) ab und läßt den Dampf (5) aus dem Kühler entweichen. Wenn beim Abkühlen des Wassers im Kühlsystem ein Vakuum entsteht, so hebt sich das Unterdruckventil (4) ab und läßt Luft nachströmen, siehe (6). Das Unterdruckventil wird durch die Feder (1) geschlossen."},{"t":"p","text":"Tritt aus irgendeinem Grunde einmal eine höhere Erwärmung ein, so ist dies für den Motor nicht schädlich, solange genügend Wasser im Kühlsystem ist."},{"t":"p","text":"Beim Öffnen des Kühlerdruckverschlusses mit Vorsicht vorgehen. Zunächst den Verschluß um eine Vierteldrehung bis zum Anschlag lockern, damit vorhandener Wasserdampf entweichen kann. Erst wenn kein Wasserdampf mehr austritt, den Verschluß mit leichtem Druck ganz abdrehen."},{"t":"p","text":"Durch Beschädigung einzelener Teile wird der Druckverschluß unwirksam und muß ausgewechselt werden."},{"t":"p","text":"Den oberen Rand des Einfüllstutzens ab und zu leicht einfetten. Dadurch läßt sich der Druckverschluß leichter aufsetzen oder abnehmen."},{"t":"h2","text":"Kühlwasserbeipaß und Thermostat"},{"t":"p","text":"Die Kühlanlage des Motors ist mit einem Beipaß (4) Bild 46, d.h. einer direkten Kühlwasserleitung vom Zylinderkopf über die Wasserpumpe zum Einlaßrohr am Kurbelgehäuse ausgerüstet. Diese Einrichtung bewirkt, daß das Kühlwasser bei kaltem Motor nicht in den Kühler fließt, sondern über den unteren Wasserkasten wieder in den Kühlwassermantel des Motors zurückgeleitet wird. Dieser direkte Umlauf innerhalb des Motors führt zu einer raschen Erwärmung des Kühlwassers, womit in kurzer Zeit eine günstige Betriebstemperatur des Motors erreicht wird."},{"t":"p","text":"Im oberen verdickten Teil des Beipasses ist der Thermostat (2) angeordnet, welcher bei zu niedriger Temperatur des Kühlwassers den Kanal zum Kühler abschließt. Das Wasser muß nun direkt durch die Kühlräume im Kurbelgehäuse und Zylinderkopf fließen."},{"t":"p","text":"Wird die Betriebstemperatur erreicht, so öffnet der Thermostat, gibt den Kanal zum Kühler frei und verschließt den Beipaß. Der Wasserumlauf erfolgt nun durch den Kühler."},{"t":"p","text":"Der Thermostat ist so abgestimmt, daß stets die günstigste Betriebstemperatur erzielt wird."},{"t":"p","text":"Thermostat und Beipaß sind wartungsfrei. Beim Ablassen des Kühlwassers entleert sich auch selbsttätig der Beipaß."},{"t":"fig","label":"Bild 46","caption":"Kühlsystem, linke Seite","legend":["1 - Kühlereinlaß","2 - Thermostat","3 - Temperaturschalter","4 - Beipaß","5 - Entlüftungschlauch vom Zylinderkopf","6 - Kühlerauslaß"],"src":"ba/fig/p34-1.jpg","w":575,"h":416},{"t":"fig","label":"Bild 47","caption":"Kühlsystem, rechte Seite","legend":["1 - Kühlereinlaß","2 - Thermostat","3 - Wasserpumpe","4 - Entlüftungsschlauch vom Zylinderkopf","5 - Spannungsregler"],"src":"ba/fig/p34-2.jpg","w":585,"h":421},{"t":"p","text":"Während der kalten Jahreszeit, in der mit Frost zu rechnen ist, muß dem Kühlwasser unbedingt eine ausreichende Menge Frostschutzmittel beigemischt werden. Wird dies nicht beachtet, so muß damit gerechnet werden, daß bei Temperaturen unter 0° C das Kühlwasser gefriert und Motor und Kühler zerstört werden."}]},{"id":"p35","printed":"34","ratio":1.5282,"blocks":[{"t":"h2","text":"Kühler"},{"t":"p","text":"Zur Aufrechterhaltung einer einwandfreien Kühlung muß das Kühlsystem außen und innen sauber sein."},{"t":"p","text":"Der äußerlich verschmutzte Kühler läßt sich durch Wasserstrahl oder Gebläse reinigen. Wasser oder Luft müssen von innen nach außen hindurchgespritzt oder -geblasen werden, da sich nur so der Schmutz löst."},{"t":"p","text":"Durch kalkarmes Wasser wird Kesselsteinansatz im Kühlsystem vermindert."},{"t":"p","text":"Daher weiches Wasser verwenden."},{"t":"p","text":"Es empfiehlt sich, dem Kühlwasser ein gutes, erprobtes Korrosionsschutzmittel beizufügen."},{"t":"p","text":"Um Schmutz aus dem Kühlsystem zu entfernen, in den Kühler eine Lösung von 1 kg Waschsoda auf 10 Liter Wasser einfüllen. Mit dieser Lösung im Kühlsystem den Motor eine Stunde laufen lassen, so daß die heiße Lösung genügend stark auf die Schmutzablagerungen einwirken kann. Nachdem der Motor abgekühlt ist, die Sodalösung ablassen und das Kühlsystem mit reinem Wasser so lange nachspülen, bis das Spülwasser klar herausfließt. Hierauf das Kühlsystem mit reinem, kalkarmen Wasser auffüllen."},{"t":"p","text":"Der Entlüftungsschlauch (4) Bild 47 zwischen Zylinderkopf und Kühler hat die Aufgabe, Luft und Dampfpolster aus dem Zylinderkopf abzuleiten. Verschraubungen gut festziehen. Undichte Verschraubungen führen zu Kühlwasserverlust."},{"t":"p","text":"Der Entlüftungsschlauch muß stets sauber sein. Er ist daraufhin öfter zu prüfen, und wenn stark verschmutzt, gegen einen neuen auszuwechseln."},{"t":"p","text":"Ein verstopfter Entlüftungsschlauch erfüllt seinen Zweck nicht und gefährdet den Motor!"},{"t":"h2","text":"Kühlwasserablaßhahn"},{"t":"p","text":"Soll aus irgendeinem Grund das Kühlwasser abgelassen werden, dasselbe in einem sauberen Behälter auffangen, wenn ihm ein Frostschutzmittel beigegeben wurde und es wieder eingefüllt werden soll."},{"t":"p","text":"Zum Entleeren des Kühlsystems den Wasserablaßhahn am Kühler öffnen, Bild 48."},{"t":"fig","label":"Bild 48","caption":"Ablaßhahn für Kühlwasser","legend":["1 - Ablaßhahn am Kühler","2 - Luftfilter"],"src":"ba/fig/p35-1.jpg","w":721,"h":527},{"t":"h2","text":"Frostschutz"},{"t":"p","text":"Das beste Mittel, das Einfrieren des Kühlers zu verhindern, ist ein frostsicherer Unterstellraum. Wo dieser nicht vorhanden ist, muß nach Beendigung der Arbeit das Wasser abgelassen werden. Wenn Frostschutzmittel verwendet werden, sind nur vertrauenswürdige Marken in den richtigen Mischungsverhältnissen zu benutzen."},{"t":"p","text":"Bei auf Frosttemperatur abgekühltem Motor das einzufüllende Kühlwasser vorher auf 50 - 70° C anwärmen."},{"t":"h2","text":"Wasserpumpe"},{"t":"p","text":"Das Wasserpumpenlager besitzt eine Fettfüllung, die für die normale Lebensdauer einer Pumpe ausreicht. Sie braucht daher weder Pflege noch Wartung."},{"t":"h2","text":"Ventilatorkeilriemen"},{"t":"p","text":"Der Ventilatorkeilriemen muß öfter auf richtige Spannung geprüft werden. Er ist richtig gespannt, wenn er zwischen den Riemenscheiben der Lichtmaschine und der Kurbelwelle 20 bis 25 mm ohne Anstrengung mit dem Daumen eingedrückt werden kann."},{"t":"p","text":"Ein neuer Riemen muß nach ca. 20 Stunden auf Spannung geprüft und, wenn nötig, nachgespannt werden. Übermässige Spannung belastet unnötig die Wasserpumpenlagerung und führt zu erhöhtem Verschleiß."},{"t":"p","text":"Das Spannen des Ventilatorkeilriemens erfolgt durch Kippen der Lichtmaschine, nachdem vorher die Halteschrauben (1) Bild 49 und die Spannschraube (2) gelöst wurden."}]},{"id":"p36","printed":"35","ratio":1.5022,"blocks":[{"t":"fig","label":"Bild 49","caption":"Spannen des Ventilatorkeilriemens","legend":["1 - Halteschrauben","2 - Spannschraube"],"src":"ba/fig/p36-1.jpg","w":724,"h":574},{"t":"p","text":"Ist die richtige Keilriemenspannung hergestellt, zuerst die Spannschraube (2) fest anziehen und anschließend die Halteschrauben (1)."},{"t":"h2","text":"Geber für Kühlwassertemperatur"},{"t":"p","text":"Der Geber ist im Thermostat eingeschraubt und überträgt die Kühlwassertemperatur auf das Fernthermometer im Kombiinstrument."},{"t":"p","text":"Steigt das Thermometer über 95° C an, den Motor mit niedriger Drehzahl und ohne Belastung weiterlaufen lassen, bis die Kühlwassertemperatur unter 95° C absinkt. Dann Motor abstellen, Ursache des Temperaturanstiegs ermitteln und Abhilfe schaffen, wie unter \"Betriebsstörungen am Motor\" beschrieben."},{"t":"fig","label":"Bild 50","caption":"","legend":["1 - Massekabel","2 - Kabel zum Thermometer"],"src":"ba/fig/p36-2.jpg","w":728,"h":559},{"t":"h2","text":"Getriebeölwechsel"},{"t":"p","text":"Nach jeweils 1600 Betriebsstunden muß das Getriebeöl gewechselt werden. Zum Ablassen des Getriebeöls die vorderen Ablaßstopfen (1) und (2) Bild 51 und den hinteren Ablaßstopfen (1) Bild 52 bei warmer Maschine herausschrauben."},{"t":"fig","label":"Bild 51","caption":"Vordere Getriebeölablaßstopfen","legend":["1 - Ablaßstopfen am vorderen Gehäuse","2 - Ablaßstopfen am hinteren Gehäuse"],"src":"ba/fig/p36-3.jpg","w":758,"h":539},{"t":"fig","label":"Bild 52","caption":"Hinterer Getriebeölablaßstopfen","legend":["1 - Ölablaßstopfen","2 - Zapfwellenschutzkappe"],"src":"ba/fig/p36-4.jpg","w":745,"h":547},{"t":"p","text":"Das frische Getriebeöl durch die Einfüllöffnung auf dem Getriebegehäusedeckel einfüllen, bis es aus der Bohrung für die Kontrollschraube (1) Bild 54 auszufließen beginnt. Für den Getriebeölwechsel werden etwa 34 Liter Getriebeöl benötigt."}]},{"id":"p37","printed":"36","ratio":1.4875,"blocks":[{"t":"fig","label":"Bild 53","caption":"Einfüllen des Getriebeöls","legend":[],"src":"ba/fig/p37-1.jpg","w":612,"h":411},{"t":"p","text":"Alle 200 Betriebsstunden den Ölstand durch Herausdrehen der Kontrollschraube (1) Bild 54 prüfen und, falls erforderlich, Öl nachfüllen."},{"t":"fig","label":"Bild 54","caption":"","legend":["1 - Getriebeölkontrollschraube","2 - Bremspedal","3 - Handbremshebel"],"src":"ba/fig/p37-2.jpg","w":604,"h":435},{"t":"h2","text":"Reinigen des Ansaugfilters"},{"t":"p","text":"(Nur bei Getriebeausführung mit Wandlergetriebe)"},{"t":"p","text":"Schlepper, die mit einem Wandlergetriebe ausgerüstet sind, haben anstelle des hinteren Ablaßstopfens ein ins Getriebegehäuse eingeschobenes Ansaugfilter."},{"t":"p","text":"Bei neuen Maschinen oder nach Getriebereparaturen muß die erste Filterreinigung nach 20, dann fortlaufend nach jeweils 200 Betriebsstunden erfolgen."},{"t":"p","text":"Das Filter wie folgt reinigen: Ansaugfilter aus dem Getriebegehäuse herausschrauben, Bild 52. Um ein Auslaufen des Getriebeöls bei zwischenzeitlicher Reinigung des Ansaugfilters zu vermeiden, die Hinterräder des Schleppers etwa 25 cm anheben oder rückwärts auf einen Hang fahren oder aber die Filteröffnung im Gehäuse mit einem Stopfen verschließen, damit das Getriebeöl nicht ausfließt."},{"t":"p","text":"Das Filter mit einer weichen Bürste in Dieselkraftstoff waschen. Keine Drahtbürste verwenden."},{"t":"p","text":"Beim Einsetzen des Ansaugfilters dieses gerade in die Bohrung einführen, damit evtl. auf dem Gehäuseboden vorhandene Unreinigkeiten nicht mit dem offenen Ende des Filters aufgenommen werden."},{"t":"h2","text":"Reinigen des Ölfilters für Wandlergetriebe"},{"t":"p","text":"Das Ölfilter für Wandlergetriebe besteht aus fünf feinmaschigen, übereinanderliegenden Siebscheiben, die auf einem Filterträger (1) Bild 56 ruhen und mit einer Rändelschraube (3) zusammengehalten werden. Jede Siebscheibe stellt ein Filterelement dar, das aus je zwei Siebteilen (4) besteht, die auseinandergenommen werden können."},{"t":"p","text":"Diese Filterelemente alle 200 Betriebsstunden reinigen. Hierzu folgendermaßen verfahren:"},{"t":"fig","label":"Bild 55","caption":"Abnehmen des Filterdeckels","legend":["1 - Deckel","2 - Rundschnurring","3 - Feder"],"src":"ba/fig/p37-3.jpg","w":603,"h":431},{"t":"p","text":"Die vier Schrauben aus dem Filtergehäusedeckel entfernen. Dabei den Deckel herunterdrücken, um dem Druck der im Gehäuse liegenden Feder (3) Bild 55 entgegenzuwirken."},{"t":"p","text":"Den Filtereinsatz herausnehmen."}]},{"id":"p38","printed":"37","ratio":1.5101,"blocks":[{"t":"p","text":"Die Rändelschraube (3) Bild 56 abschrauben, die Siebscheiben vom Filterträger (1) abnehmen und zerlegen."},{"t":"fig","label":"Bild 56","caption":"","legend":["1 - Filterträger","2 - Siebscheiben","3 - Rändelschraube","4 - Auseinandergenommene Siebteile eines Filterelementes"],"src":"ba/fig/p38-1.jpg","w":541,"h":386},{"t":"p","text":"Die Siebscheiben mit weichem Pinsel in Dieselkraftstoff oder Petroleum auswaschen. Keine Drahtbürste oder metallische Werkzeuge verwenden, da die feinen Siebmaschen damit zerstört würden."},{"t":"p","text":"Die gereinigten Siebscheiben wieder zusammensetzen, auf den Filterträger aufschieben und mit der Rändelschraube festziehen. Das ganze Filter mit Feder (3) Bild 55 in das Gehäuse einsetzen, Rundschnurring (2) einlegen und Filterdeckel anschrauben."},{"t":"h2","text":"Pflege der Regelhydraulik"},{"t":"fig","label":"Bild 57","caption":"Ablassen des Hydrauliköls","legend":["1 - Ablaßstopfen","2 - Regelgeberschwinge"],"src":"ba/fig/p38-2.jpg","w":590,"h":456},{"t":"p","text":"Das Hydrauliköl muß erstmalig nach 200 Betriebsstunden und dann fortlaufend nach jeweils 800 Betriebsstunden erneuert werden."},{"t":"p","text":"Das Ansaugfilter (1) Bild 58 nach den ersten 20 und nach den ersten 200 Betriebsstunden reinigen."},{"t":"p","text":"Danach ist die Reinigung des Filters alle 800 Betriebsstunden zusammen mit dem Hydraulikölwechsel vorzunehmen."},{"t":"p","text":"Hierzu Kraftheber ganz absenken."},{"t":"p","text":"Ablaßstopfen (1) Bild 57 herausschrauben und das Öl in einen sauberen Behälter laufen lassen. An die Öffnung ein Fangblech oder einen Trichter ansetzen, um das Öl in den Behälter zu leiten."},{"t":"p","text":"Saugleitung lösen. Ansaugfilter (1) Bild 58 herausschrauben und sorgfältig mit einer weichen Bürste in Dieselkraftstoff reinigen. Zum Trocknen das Filter von innen nach außen mit Druckluft durchblasen."},{"t":"fig","label":"Bild 58","caption":"","legend":["1 - Ansaugfilter","2 - Absenkdrossel"],"src":"ba/fig/p38-3.jpg","w":580,"h":412},{"t":"fig","label":"Bild 59","caption":"","legend":["1 - Ölmeßstab, obere Kerbmarke","2 - untere Kerbmarke","3 - Belüftungsfilter","4 - Dichtring"],"src":"ba/fig/p38-4.jpg","w":583,"h":431}]},{"id":"p39","printed":"38","ratio":1.5337,"blocks":[{"t":"p","text":"Danach das Filter einsetzen, Saugleitung anschließen und Ablaßstopfen einschrauben."},{"t":"p","text":"Bei der Filterreinigung nach den ersten 20 Betriebsstunden kann das abgelassene Hydrauliköl wieder verwendet werden. Es ist jedoch beim Einfüllen durch ein Sieb mit 0.05 mm Maschenweite zu filtern."},{"t":"p","text":"Zum Einfüllen des Hydrauliköls Belüftungsfilter (3) Bild 59 herausschrauben."},{"t":"p","text":"Alle 200 Stunden den Ölstand im Hydraulikgehäuse prüfen. Belüftungsfilter herausschrauben und Ölmeßstab abwischen. Um den Ölstand zu messen, Belüftungsfilter mit Ölmeßstab nicht einschrauben, sondern auf den Rand der Bohrung aufsetzen, Bild 59."},{"t":"p","text":"Wenn erforderlich, Öl nachfüllen. Belüftungsfilter einschrauben."},{"t":"p","text":"Zum Entlüften der Anlage nach dem Auffüllen, nach einer Reinigung des Ansaugfilters oder beim Ölwechsel, Motor anlassen und kurz mit voller Drehzahl laufen lassen. Dabei mehrmals den Lageneinstellhebel (1) Bild 20 über seinen Gesamtweg auf- und ab bewegen. Danach Hebel in tiefster Stellung belassen, so daß auch die Lastarme ganz nach unten stehen. Motor abstellen."},{"t":"p","text":"Erneut Ölstand am Meßstab prüfen und bis zu oberen Ölstandmarke nachfüllen. Belüftungsfilter fest einschrauben."},{"t":"p","text":"Bei den vorstehenden Arbeiten streng darauf achten, daß kein Wasser, Schmutz oder sonstige Fremdkörper in das Hydraulikgehäuse gelangen."},{"t":"p","text":"Das Belüftungsfilter in sauberem Dieselkraftstoff auswaschen. Den Ölstand mit Ölmeßstab prüfen und bei ordnungsgemäßer Füllung Belüftungsfilter mit Ölmeßstab fest einschrauben."},{"t":"p","text":"Auf keinen Fall die Bremsscheiben der Hebel (1) und (2) Bild 20 ölen. Die Hebel sind auf einen gewissen Widerstand eingestellt, damit sie sich nicht selbsttätig verstellen können. Öl würde die Bremsscheiben unbrauchbar machen."},{"t":"h2","text":"Lenkgetriebe"},{"t":"p","text":"Alle 200 Betriebsstunden den Ölstand im Lenkgetriebe prüfen und, wenn erforderlich, nachfüllen."},{"t":"p","text":"Verschlußstopfen (2) Bild 60 herausdrehen und das Lenkgetriebe mit SAE 90 Hypoidöl auffüllen, bis es aus der Einfüllöffnung auszufließen beginnt, Bild 60. Dabei darauf achten, daß keine Luftpolster im Gehäuse eine Vollfüllung vortäuschen."},{"t":"fig","label":"Bild 60","caption":"Lenkgetriebe","legend":["1 - Einfüllbohrung","2 - Verschlußstopfen"],"src":"ba/fig/p39-1.jpg","w":650,"h":479},{"t":"h2","text":"Abschmieren"},{"t":"p","text":"Alle mit Schmiernippel versehenen Schmierstellen mit gutem Mehrzweckfett in Abständen, wie im Schmierplan vorgeschrieben, abschmieren."},{"t":"p","text":"Dabei darauf achten, daß alle Schmiernippel Fett durchlassen. Beschädigte Schmiernippel auswechseln."},{"t":"p","text":"Die Schmiernippel der Vorderachslagerung sind zur besseren Auffindung in Bild 61 gezeigt."},{"t":"fig","label":"Bild 61","caption":"Schmiernippel an der Vorderachse","legend":["1 - Vorderachslager, hinten","2 - Vorderachslager, vorn","3 - Umlenkhebel"],"src":"ba/fig/p39-2.jpg","w":646,"h":461}]},{"id":"p40","printed":"39","ratio":1.4822,"blocks":[{"t":"h1","text":"Einstellungen"},{"t":"h2","text":"Kupplung"},{"t":"fig","label":"Bild 62","caption":"Äußere Ausrückteile der Zweifachkupplung","legend":["1 - Anschlagschraube","2 - Kupplungspedal","3 - Gabelstück (Fußkupplung)","4 - Kopfstift","5 - Zapfwellenkupplung (Handhebel)","6 - Gabelstück (Handkupplung)","7 - Kopfstift (Handkupplung)"],"src":"ba/fig/p40-1.jpg","w":605,"h":435},{"t":"p","text":"Bei richtiger Einstellung hat das Kupplungspedal (2) Bild 62 einen Freigang (toten Gang) von etwa 35 mm, bevor der Auskupplungsvorgang beginnt. Mit Abnutzung der Kupplungsbeläge verringert sich der Freigang. Die Kupplung nachstellen, wenn der Freigang nur noch etwa 10 mm beträgt."},{"t":"fig","label":"Bild 63","caption":"Äußere Ausrückteile der Einfachkupplung","legend":["1 - Anschlagschraube","2 - Kupplungspedal","3 - Gabelstück","4 - Kopfstift"],"src":"ba/fig/p40-2.jpg","w":618,"h":459},{"t":"p","text":"Das Nachstellen vornehmen, wie folgt:"},{"t":"p","text":"Splint entfernen und Kopfstift (4) Bild 63 herausnehmen. Das Gabelstück (3) um soviel vom Gewindebolzen abschrauben, wie erforderlich ist, um den Freigang am Kupplungspedal wieder auf 35 mm zu erhöhen."},{"t":"p","text":"Nach dieser Einstellung prüfen, ob der Abstand des Kupplungspedals zur Plattform etwa 135 mm beträgt. Ist dieser Abstand nicht gegeben, die richtige Einstellung mit der Anschlagschraube (1) vornehmen."},{"t":"p","text":"Der Zapfwellenhandhebel hat ein fühlbares Spiel, bevor der Auskupplungsvorgang beginnt. Dieses Spiel ist bei neuer Maschine gut fühlbar und dementsprechend auch die Verringerung des Spieles, wenn Verschleiß der Kupplungsbeläge vorliegt. Eine Einstellung muß vorgenommen werden, wenn nur noch ein geringes Spiel beim Auskupplungsvorgang fühlbar ist."},{"t":"p","text":"Kopfstift (7) Bild 62 entfernen und das Gabelstück (6) um soviel von dem Gewindebolzen abschrauben, wie erforderlich ist, um den wie bei neuer Maschine fühlbaren Freigang einzustellen."},{"t":"h2","text":"Nachstellen der Lamellenkupplung"},{"t":"p","text":"(Nur bei Agriomatic-Getriebe)"},{"t":"p","text":"Sobald an der Lamellenkupplung bei schwerer Belastung in der Ackergruppe Anzeichen des Durchrutschens bemerkbar werden, muß sie an den Einstellexzentern an beiden Seiten des Getriebes nachgestellt werden."},{"t":"p","text":"Diese Einstellexzenter sind auch an den Standardgetriebeausführungen vorhanden, dienen aber nur zur Einstellung nach Reparaturen an der Gruppenschaltung."},{"t":"fig","label":"Bild 63a","caption":"Linke Getriebeseite / Rechte Getriebeseite","legend":["1 - Muttern","2 - Einstellexzenter","3 - Einstellkerben","4 - Gehäusemarkierung"],"src":"ba/fig/p40-3.jpg","w":619,"h":296}]},{"id":"p41","printed":"40","ratio":1.5307,"blocks":[{"t":"p","text":"Das Nachstellen der Lamellenkupplung wie folgt vornehmen:"},{"t":"p","text":"Die Muttern (1) Bild 63a der Einstellexzenter auf beiden Seiten des Getriebes lösen."},{"t":"p","text":"Einstellexzenter (2) um je eine Kerbe (3) von der Gehäusemarke (4) aus in Pfeilrichtung drehen. Durch kurzes Hin- und Herbewegen des Agriomatic-Hebels in der Mittelstellung wird diese Arbeit erleichtert."},{"t":"p","text":"Die Muttern der Einstellexzenter wieder anziehen. Durch Fahrprüfung feststellen, ob Abhilfe erfolgt ist. Falls nicht ausreichend, beide Einstellexzenter um eine weitere Kerbe nachstellen."},{"t":"p","text":"Die Einstellexzenter müssen auf beiden Seiten gleichmässig eingestellt werden, d.h., wenn auf der linken Seite die 5. Kerbe mit der Gehäusemarke übereinstimmt, so muß dies auch auf der rechten Seite der Fall sein. Ungleichmäßige Einstellung hat Rutschen der Lamellenkupplung, raschen Verschleiß und schließlich Zerstörung des Drucklagers zur Folge."},{"t":"h2","text":"Fußbremse"},{"t":"p","text":"Der Schlepper ist mit Scheibenbremsen ausgerüstet, die beiderseitig auf das Getriebe wirken."},{"t":"p","text":"Wenn die Bremspedale (1) Bild 64 durch die Feststellasche (2) verbunden sind, werden beide Bremsen gleichzeitig betätigt. Getrennt wirkt das rechte Bremspedal auf die rechte Bremse zur Lenkunterstützung bei scharfen Rechtskurven."},{"t":"fig","label":"Bild 64","caption":"Rechte Seite der Bremseinrichtung","legend":["1 - Bremspedale","2 - Feststellasche","3 - Bremsgestänge","4 - Einstellgabel","5 - Kontermuttern","6 - Einstellstange","7 - Schmiernippel","8 - Differentialsperre"],"src":"ba/fig/p41-1.jpg","w":693,"h":509},{"t":"p","text":"Das linke Bremspedal wirkt im gleichen Sinne linksseitig. Bei Straßenfahrt müssen die Bremspedale durch die Feststellasche miteinander verbunden werden."},{"t":"p","text":"Die Bremsen müssen nachgestellt werden, wenn sich die Bremspedale zu weit durchtreten lassen. Die richtige Einstellung ist vorhanden, wenn die Bremspedale, gemessen an der Plattform, ca. 15 mm toten Gang haben."},{"t":"fig","label":"Bild 65","caption":"Linke Seite der Bremseinrichtung","legend":["1 - Kontermuttern","2 - Einstellstange","3 - Einstellgabel","4 - Schmiernippel"],"src":"ba/fig/p41-2.jpg","w":733,"h":560},{"t":"p","text":"Nachstellen der Bremsen wie folgt vornehmen:"},{"t":"p","text":"Die Kontermuttern (1) Bild 65 lösen."},{"t":"p","text":"Durch Rechtsdrehen der Einstellstange (2) wird die Bremse nachgestellt."},{"t":"p","text":"Auf diese Weise die Bremsen an beiden Seiten des Schleppers gleichmäßig einstellen, siehe auch (5 und 6) Bild 64. Zur Prüfung der Einstellung Bremsversuche durchführen."},{"t":"p","text":"Nach der Einstellung die Kontermuttern (1) und (5) fest anziehen."},{"t":"p","text":"Beim Fahren mit Lastanhängern ist der Zustand der Bremsen besonders wichtig. Bei Talfahrt ist der Last entsprechend rechtzeitig der 2. oder 1. Gang des Schleppers einzuschalten."},{"t":"p","text":"Wenn das Gesamtgewicht des beladenen Anhängers größer ist als das des Schleppers oder wenn der Anhänger mehr als eine Achse hat, muß der Anhänger eine eigene Bremseinrichtung haben."},{"t":"h2","text":"Handbremse"},{"t":"p","text":"Die Handbremse dient als Feststellbremse. Sie wirkt als Bandbremse auf das Differential und ist unabhängig von der übrigen Bremseinrichtung des Schleppers."}]},{"id":"p42","printed":"41","ratio":1.4853,"blocks":[{"t":"fig","label":"Bild 66","caption":"","legend":["1 - Handbremshebel","2 - Zahnsegment","3 - Einstellhebel","4 - Einstellschraube","5 - Kontermutter","6 - Bremsband","7 - Stellschrauben"],"src":"ba/fig/p42-1.jpg","w":681,"h":414},{"t":"p","text":"Wenn sich der Handbremshebel zu weit nach hinten ziehen läßt, muß die Bremse nachgestellt werden. Hierzu den Handbremshebel (1) Bild 66 ganz nach vorn drücken. Die Stellschrauben (7) und die Kontermutter (5) lösen. Die Einstellschraube (4) zwei bis drei Umdrehungen einschrauben und prüfen, ob Abhilfe geschaffen wurde."},{"t":"p","text":"Die Handbremse ist richtig eingestellt, wenn sich der Handbremshebel (1) bis zum zweiten oder dritten Zahn des Segmentes (2) zurückziehen läßt. Nach erfolgter Einstellung die Kontermutter (5) wieder festziehen."},{"t":"p","text":"Wenn die Einstellmöglichkeit erschöpft ist, müssen die Bremsbeläge erneuert werden."},{"t":"h2","text":"Spurverstellung der Vorderräder"},{"t":"p","text":"Der Schlepper wird mit einer Spureinstellung von 1320 mm ausgeliefert."},{"t":"p","text":"Durch Versetzen der Vorderachsverlängerungen können Spurweiten von 1220 - 1720 mm um je 100 mm steigend eingestellt werden. Die Achsverlängerungen sind mit je 8 Bohrungen versehen."},{"t":"p","text":"Im einzelnen wie folgt verfahren:"},{"t":"p","text":"Schlepper unter der Vorderachse aufbocken. Schrauben (1) Bild 67 entfernen und Federsicherung (3) herausziehen. Klemmschrauben (2) lösen. Achsverlängerung auf die gewünschte Spurbreite herausziehen und mit den Schrauben festziehen. Durch Wenden der Vorderräder kann die Spur zusätzlich um 140 mm erweitert werden."},{"t":"fig","label":"Bild 67","caption":"","legend":["1 - Befestigungsschrauben","2 - Klemmschrauben","3 - Federsicherung"],"src":"ba/fig/p42-2.jpg","w":658,"h":470},{"t":"p","text":"Bei jeder Änderung der Spurbreite müssen auch die beiden Spurstangen entsprechend eingestellt werden. Federsicherung (3) in die entsprechende Bohrung der Verlängerung einsetzen und die Klemmschrauben (2) der Spannschellen wieder festanziehen. Nach jeder Spurverstellung empfiehlt sich ein Überprüfen der Vorspur."},{"t":"p","text":"Die Vorderachsverlängerung von Zeit zu Zeit mit Mehrzweckfett schmieren."},{"t":"h2","text":"Einstellen der Vorspur"},{"t":"p","text":"Die Vorderräder müssen 2 - 4 mm Vorspur haben. Zunächst den Abstand vorn an der Felgeninnenkante in Höhe der Radnaben messen, Bild 68."},{"t":"fig","label":"Bild 68","caption":"Messen der Vorspur","legend":["1 - Meßlatte","2 - Kreidemarkierung"],"src":"ba/fig/p42-3.jpg","w":661,"h":517},{"t":"p","text":"Die Meßstellen mit Kreide markieren und die Räder um eine halbe Umdrehung nach hinten weiterdrehen. Das sich in dieser Stellung ergebende Maß muß 2 - 4 mm größer sein als bei der vorderen Messung."}]},{"id":"p43","printed":"42","ratio":1.4945,"blocks":[{"t":"p","text":"Die Meßlatte nicht gegen das Felgenhorn (1) Bild 69 sondern gegen die Fläche (2) setzen."},{"t":"fig","label":"Bild 69","caption":"","legend":["1 - Felgenhorn","2 - Meßfläche"],"src":"ba/fig/p43-1.jpg","w":510,"h":401},{"t":"p","text":"Werden Abweichungen festgestellt, die Klemmschraube (2) Bild 70 und die Schelle (3) lösen. Den Kugelzapfen (1) aus der Halterung herausnehmen und durch Ein- oder Ausschrauben die Spurstange verkürzen oder verlängern."},{"t":"fig","label":"Bild 70","caption":"","legend":["1 - Kugelzapfen","2 - Klemmschraube für Kugelzapfen","3 - Schelle für Feineinstellung"],"src":"ba/fig/p43-2.jpg","w":604,"h":453},{"t":"p","text":"Die Einstellung der Vorspur von Zeit zu Zeit prüfen. Beim Messen und Einstellen der Vorspur muß der Schlepper waagerecht und die Lenkung in Mittelstellung stehen."},{"t":"h2","text":"Nachstellen der Vorderradlager"},{"t":"p","text":"Bald nach der ersten Inbetriebnahme des Schleppers, spätestens aber nach 50 Betriebsstunden, die Vorderräder überprüfen und feststellen, ob die Radlager locker geworden sind."},{"t":"p","text":"Nach Entfernen der Schutzkappen Bild 71 können die Lagereinstellmuttern nachgestellt werden, Bild 72. Dazu muß der Schlepper vorn aufgebockt sein."},{"t":"fig","label":"Bild 71","caption":"Abnehmen der Schutzkappe","legend":[],"src":"ba/fig/p43-3.jpg","w":669,"h":677},{"t":"fig","label":"Bild 72","caption":"Einstellen der Radlager","legend":[],"src":"ba/fig/p43-4.jpg","w":673,"h":750},{"t":"p","text":"Die Lagereinstellmutter so weit anziehen, bis sich ein fühlbarer Widerstand ergibt. Während des Anziehens muß das Rad fortlaufend gedreht werden. Anschließend die Kronenmutter bis zur nächstmöglichen Übereinstimmung mit dem Splintloch zurückdrehen und versplinten. Nach der Einstellung müssen die Vorderräder leicht laufen (spielen)."}]},{"id":"p44","printed":"43","ratio":1.5137,"blocks":[{"t":"p","text":"Beim Wiederanbringen der Lagerkappe darauf achten, daß diese sauber und vorschriftsmäßig mit Fett gefüllt ist."},{"t":"p","text":"Alle 1600 Betriebsstunden die Prüfung der Radlager wiederholen. Einmal jährlich die Radnaben abnehmen, sie gründlich in Dieselkraftstoff auswaschen und mit frischem Fett füllen. Die Radlager, wie vorstehend beschrieben, neu einstellen."},{"t":"h2","text":"Bereifung"},{"t":"p","text":"Die Reifen müssen jeweils folgenden Luftdruck haben:"},{"t":"table","caption":"","head":["","",""],"rows":[["Vorderräder:","für Straßenfahrt:","2,0 atü"],["","bei Feldarbeit:","1,5-2,0 atü"],["Hinterräder:","für Straßenfahrt:","1,5 atü"],["","bei Feldarbeit","0,8-1,0 atü"]]},{"t":"p","text":"Die Radschüsselmuttern der Vorder- und Hinterräder in der ersten Betriebszeit öfter nachziehen."},{"t":"p","text":"Das Anzugsmoment beträgt für die"},{"t":"table","caption":"","head":["",""],"rows":[["Vorderräder","7 mkg"],["Hinterräder","22-25 mkg"],["Hinterrad-Felgenschrauben","18 mkg"]]},{"t":"p","text":"Stets darauf achten, daß sich diese Verschraubungen nicht lockern."},{"t":"h2","text":"Spurverstellung der Hinterräder"},{"t":"p","text":"Mit den folgenden Radveränderungen können Spurweiten von 1280 - 1880 mm in Abständen von jeweils 100 mm eingestellt werden; siehe auch Bild 73."},{"t":"list","ordered":true,"items":["Radschlüssel mit der Wölbung nach innen oder mit der Wölbung nach außen.","Felgen mit der Innen- oder Außenseite der Felgenhalter an den Radschüsseln liegend.","Ein Rad mit der Radschüsselwölbung nach außen und das andere mit der Radschüsselwölbung nach innen."]},{"t":"p","text":"Beim Einstellen der verschiedenen Spurweiten auf die Laufrichtung des Gummiprofils achten."},{"t":"p","text":"Die Räder jeweils so anbringen, daß der sich auf den Reifen befindliche Pfeil in Laufrichtung des Rades zeigt."},{"t":"p","text":"Radmuttern mit dem vorgeschriebenen Drehmoment festziehen. Den Sitz der Radmuttern von Zeit zu Zeit nachprüfen und, falls erforderlich, nachziehen."}]},{"id":"p45","printed":"44","ratio":1.4966,"blocks":[{"t":"fig","label":"Bild 73","caption":"Beispiele für die Spurverstellung der Hinterräder","legend":["1 = 1280 mm","2 - 1380 mm","3 = 1380 mm","4 = 1480 mm","5 = 1680 mm","6 = 1780 mm","7 = 1780 mm","8 = 1880 mm"],"src":"ba/fig/p45-1.jpg","w":1100,"h":1270},{"t":"p","text":"Die Abbildungen veranschaulichen die symmetrischen Verstellmöglichkeiten. Durch die asymmetrischen Verstellmöglichkeiten (siehe Seite 43 \"Spurverstellung der Hinterräder\" unter 3) ergeben sich Zwischenwerte von jeweils 50 mm, die zwischen den hier angegebenen liegen."}]},{"id":"p46","printed":"45","ratio":1.5217,"blocks":[{"t":"h1","text":"Elektrische Anlage"},{"t":"p","text":"Der Schlepper muß laut Straßenverkehrsordnung bei Benutzung öffentlicher Wege mit elektrischer Beleuchtung und Fahrtrichtungsanzeiger ausgerüstet sein. Um immer eine funktionsfähige Anlage zu haben, ist es wichtig, daß alle Armaturen, Leitungsanschlüsse und Kabel in einwandfreiem Zustand gehalten werden."},{"t":"h2","text":"Batterie"},{"t":"p","text":"Der Schlepper ist mit einer 12V Batterie ausgerüstet. Die Batterie kommt geladen und mit Säurefüllung oder trocken vorgeladen mit dem Schlepper zum Versand."},{"t":"p","text":"Trocken vorgeladene Batterien erhalten kurz vor der Auslieferung des Schleppers eine Säurefüllung. Sie sind dann nach 3 - 5 Stunden betriebsfertig."},{"t":"fig","label":"Bild 74","caption":"Ausbau der Batterie","legend":[],"src":"ba/fig/p46-1.jpg","w":685,"h":507},{"t":"p","text":"Um die Batterie vom Schlepper abzubauen, die Klemmschrauben Bild 74 lösen, Halteband und Batteriedeckel abnehmen."},{"t":"p","text":"Massekabel (2) Bild 75 zuerst und dann das Pluskabel (1) abnehmen. Zum Abnehmen des Pluskabels die Handmutter (3) abschrauben."},{"t":"fig","label":"Bild 75","caption":"","legend":["1 - Pluskabel","2 - Massekabel","3 - Handmutter"],"src":"ba/fig/p46-2.jpg","w":688,"h":518},{"t":"p","text":"Beim Einbau der Batterie darauf achten, daß zuerst die Plusklemme an den Pluspol (+) angebracht wird und dann die Minusklemme (Massekabel) an den Minuspol (-)."},{"t":"p","text":"Auf saubere metallische Auflageflächen achten, nötigenfalls abkratzen und mit Polfett einfetten."},{"t":"p","text":"Alle 200 Betriebsstunden den Säurestand prüfen. Die Säure muß etwa 1 cm über den Plattenkanten stehen."},{"t":"p","text":"Zur Pflege der Batterie die Vorschriften der Herstellerfirma beachten. Diese Vorschriften, zusammen mit einem Garantieschein, sind diesem Handbuch beigefügt. Es ist notwendig, die Behandlungsvorschriften für die Batterie sorgfältig durchzulesen und genau zu befolgen, denn eine sachgemäße Wartung der Batterie ist sehr wichtig für ihre Lebensdauer und störungsfreie Arbeit."},{"t":"h2","text":"Sicherungen"},{"t":"p","text":"Nach dem Abschrauben des Sicherungsdeckels (1) Bild 76 liegen die Sicherungen frei."},{"t":"fig","label":"Bild 76","caption":"","legend":["1 - Sicherungsdeckel","2 - Halteschraube","3 - 5 Ampere Sicherung","4 - 8 Ampere Sicherungen"],"src":"ba/fig/p46-3.jpg","w":676,"h":507},{"t":"p","text":"Defekte Sicherungen nie flicken, sondern durch neue ersetzen."},{"t":"h2","text":"Scheinwerfer"},{"t":"p","text":"Defekte Glühlampen sofort auswechseln."},{"t":"p","text":"Neue Glühlampen nie mit bloßen Fingern oder fettigen Lappen anfassen, weil an der Glühlampe Fettspuren zurückbleiben."},{"t":"p","text":"Durch Erwärmung verdampfen diese Rückstände und schlagen auf den Reflektor nieder, was eine Beeinträchtigung der Leuchtwirkung bedeutet."},{"t":"p","text":"Jedes Berühren des Reflektors unbedingt vermeiden."},{"t":"p","text":"Die Scheinwerfer nur zum Auswechseln einer Glühlampe oder zu Reparaturen öffnen."}]},{"id":"p47","printed":"46","ratio":1.5338,"blocks":[{"t":"h2","text":"Lichtmaschine, Anlasser und Spannungsregler"},{"t":"p","text":"Lichtmaschine und Anlasser bedürfen keiner besonderen Wartung. Nach etwa 1000 Betriebsstunden oder einmal im Jahr Reinigung und Abschmieren in einer Spezialwerkstatt vornehmen lassen."},{"t":"p","text":"Der unter der Motorhaube an der rechten Seite auf dem Kühler angebrachte Spannungsregler (5) Bild 47 sorgt dafür, daß der erzeugte Strom dem jeweiligen Ladestand der Batterie angepaßt ist. Bei Kabelanschlüssen zwischen Lichtmaschine und Spannungsregler darauf achten, daß die Anschlüsse D+, D- und DF gleichlautend miteinander verbunden werden."}]},{"id":"p48","printed":"47","ratio":1.5342,"blocks":[{"t":"h1","text":"NOTIZEN"}]},{"id":"p49","printed":null,"ratio":1.5903,"blocks":[{"t":"h1","text":"Schaltplan G167"},{"t":"p","text":"Für Schlepper mit Geschwindigkeiten über 20 km/std. (in der Kabelliste mit ** gekennzeichnet)."},{"t":"plan","variant":"**"}],"label":"Schaltplan G167 (Beilage)"},{"id":"p50","printed":"48","ratio":1.5,"blocks":[{"t":"h1","text":"Schaltplan G168"},{"t":"p","text":"Für Schlepper mit Geschwindigkeiten bis 20 km/std. (in der Kabelliste mit * gekennzeichnet)."},{"t":"plan","variant":"*"}]},{"id":"p51","printed":"49","ratio":1.5247,"blocks":[{"t":"h1","text":"Bauteile und Kabelliste"},{"t":"h2","text":"Bauteile"},{"t":"parts"},{"t":"h2","text":"Kabel 1 bis 19"},{"t":"cables","from":1,"to":19},{"t":"p","text":"* Nur für Schlepper mit Geschwindigkeiten bis 20 km/std.\n** Nur für Schlepper mit Geschwindigkeiten über 20 km/std."}]},{"id":"p52","printed":null,"ratio":1.5308,"blocks":[{"t":"h2","text":"Kabelliste: Kabel 20 bis 64"},{"t":"cables","from":20,"to":64}],"label":"Kabelliste 20–64 (Beilage)"},{"id":"p53","printed":null,"ratio":1.6058,"blocks":[{"t":"h2","text":"Kabelliste: Kabel 65 bis 94"},{"t":"cables","from":65,"to":94}],"label":"Kabelliste 65–94 (Beilage)"},{"id":"p54","printed":"50","ratio":1.5648,"blocks":[{"t":"h1","text":"Notizen"}]},{"id":"p55","printed":"51","ratio":1.4766,"blocks":[{"t":"h1","text":"Behandlung des Schleppers bei längeren Arbeitspausen (etwa 3 Monate und länger)"},{"t":"h2","text":"Vor der Arbeitspause"},{"t":"p","text":"Den Schlepper äußerlich gut gereinigt an einem geschützten und trockenen Ort unterstellen. Nachstehende Vorsichtsmaßnahmen befolgen:"},{"t":"p","text":"Motoröl ablassen."},{"t":"p","text":"Konservierungsöl bis zur oberen Marke des Ölmeßstabes auffüllen."},{"t":"p","text":"Ölfilter reinigen und wieder zusammensetzen."},{"t":"p","text":"Kraftstoffbehälter entleeren und spülen."},{"t":"p","text":"In den Kraftstoffbehälter 3 Liter Petroleum einfüllen."},{"t":"p","text":"Motor 15 Minuten mit Petroleum bei mittlerer Drehzahl laufen lassen."},{"t":"p","text":"Wasser aus dem Kühler ablassen."},{"t":"p","text":"Durch die Glühkerzenlöcher je einen Eßlöffel voll Konservierungsöl einfüllen und Motor mittels Anlassers einige Male durchdrehen. Der Gashebel muß dabei in Nullstellung stehen."},{"t":"p","text":"Batterie frostfrei aufbewahren und alle 6 Wochen nachladen."},{"t":"p","text":"Zur Schonung der Reifen den Schlepper aufbocken."},{"t":"p","text":"Wasserfüllung der Reifen ohne Frostschutz ablassen."},{"t":"h2","text":"Nach der Arbeitspause"},{"t":"p","text":"Vor dem Anlassen des Motors:"},{"t":"p","text":"Batterie entladen und wieder aufladen."},{"t":"p","text":"Kühlwasser und Kraftstoff auffüllen."},{"t":"p","text":"Kraftstoffsystem entlüften."},{"t":"p","text":"Das gereinigte Luftfilter vorschriftsmäßig mit Motoröl füllen."},{"t":"p","text":"Den Motor einige Minuten laufen lassen, bevor er auf hohe Drehzahl gebracht und belastet wird."},{"t":"p","text":"Das Konsevierungsöl kann einige Stunden während der Arbeit des Motors darin verbleiben. Es muß danach gegen das vorgeschriebene Motoröl SAE 20 HD ausgewechselt werden."},{"t":"p","text":"Reifenluftdruck prüfen."}]},{"id":"p56","printed":"52","ratio":1.5195,"blocks":[{"t":"h1","text":"Betriebsstörungen am Motor und deren Ursachen"},{"t":"p","text":"Zuerst die Ursache der Störung feststellen, bevor Neueinstellungen vorgenommen werden. Wenn irgendwelche Einstellungen gemacht werden, sich die ursprüngliche Einstellung merken, um sie wieder herstellen zu können, wenn durch die Neueinstellung keine Abhilfe geschaffen wurde."},{"t":"h2","text":"Uberhitzung"},{"t":"p","text":"Kühlwasservorrat ungenügend, Ventilatorkeilriemen rutscht, Belastung zu groß, das Innere des Kühlers oder Kurbelgehäuses durch Schmutz oder Kesselstein verstopft, die Kühlerlamellen mit Schmutz oder Spreu angefüllt, Einspritzpumpe falsch eingestellt. Thermostat gestört."},{"t":"h2","text":"Motor springt nicht an"},{"t":"p","text":"Kraftstoffhahn geschlossen. Nicht hinreichend vorgeglüht, Kraftstoffbehälter leer, Einspritzpumpe arbeitet nicht, Gashebel nicht betätigt, Einspritzpumpe spritzt zu früh oder zu spät ein, weil nicht richtig eingestellt, Einspritzdüsen arbeiten nicht, Stabglühkerzen beschädigt, Luft im Kraftstoffsystem oder Leitungen verstopft. Die Ventile schließen nicht oder sitzen fest."},{"t":"h2","text":"Motor arbeitet unregelmäßig"},{"t":"p","text":"Kraftstoffilter verstopft, Luft im Kraftstoffsystem, Einspritzpumpenkolben bleiben ab und zu hängen, Düsen schadhaft."},{"t":"h2","text":"Motor leistet zu wenig"},{"t":"p","text":"Kraftstoffilter verstopft, Einspritzpumpe spritzt zu wenig ein, Ventile undicht, Gasgestänge nicht richtig eingestellt, Ölbadluftfilter verstopft, Kupplung rutscht, Kraftstoffleitungen lassen nicht genügend Kraftstoff durch."},{"t":"h2","text":"Öldruck mangelhaft"},{"t":"p","text":"Motor zu heiß, Ölvorrat ungenügend, Öl nicht von vorschriftsmäßiger Beschaffenheit, Schmutz im Überdruckventil, Ölpumpensieb verstopft, Öldruckschalter oder Kontrollampe beschädigt oder Ölpumpe arbeitet nicht, stark abgenutzte Kurbelwellen- und Pleuellager."},{"t":"h2","text":"Klopfen im Motor"},{"t":"p","text":"Der Motor ist zu kalt, Einspritzdüsen tropfen nach, Einspritzpumpe spritzt zu früh ein, Ventile klemmen oder sind falsch eingestellt, Kolbenbolzen, Pleuelstangen, Nockenwelle oder Kurbelwellenlager locker, Kolbenringe zerbrochen oder Kolben locker."},{"t":"h2","text":"Kompression ungenügend"},{"t":"p","text":"Verschmutzte, schadhafte oder schlecht eingestellte Ventile, Kolbenringe sitzen fest, sind abgenutzt oder gebrochen, Kolben stark abgenutzt, Zylinderkopfdichtung undicht, Zylinderlaufbüchsen ausgelaufen."}]},{"id":"p57","printed":"53","ratio":1.5195,"blocks":[{"t":"h1","text":"Stichwortverzeichnis"},{"t":"h2","text":"A"},{"t":"table","caption":"","head":["Stichwort","Seite"],"rows":[["Ablassen des Kühlwassers","34"],["Abreißkupplungen","21"],["Ansaugfilter, Getriebe","36"],["Abschmieren","38"],["Absenkdrossel","20"],["Abstellen des Motors","13"],["Agriomatic-Hebel","11"],["Anbau von Pflügen","20"],["Anfahren des Schleppers","12"],["Anhängerkupplung","17"],["Anlasser","46"],["Anlassen des Motors","12"],["Armaturen","8"],["Anzugsmomente für Radmuttern","43"]]},{"t":"h2","text":"B"},{"t":"table","caption":"","head":["Stichwort","Seite"],"rows":[["Batterie","45"],["Bedienungshebel","9, 20"],["Behandlung des Schleppers bei Arbeitspausen","51"],["Beipaß","33"],["Beleuchtung","11"],["Bereifung","43"],["Betriebsstörungen am Motor","52"],["Blinkerkontrolle","9"],["Blinkschalter","11"],["Blocksteuergeräte","21"],["Bremsen","40"]]},{"t":"h2","text":"D"},{"t":"table","caption":"","head":["Stichwort","Seite"],"rows":[["Differentialsperre","11"],["Dreipunktaufhängung","18"],["Düsen","30"]]},{"t":"h2","text":"E"},{"t":"table","caption":"","head":["Stichwort","Seite"],"rows":[["Einlaufen des Schleppers","12"],["Einspritzdüsen","30"],["Einspritzleitungen","30"],["Einspritzpumpe","28"],["Einspritzpumpe, Wartung","28"],["Einstellungen","39"],["Elektrische Anlage","45"],["Entlüften des Kraftstoffsystems","30"]]},{"t":"h2","text":"F"},{"t":"table","caption":"","head":["Stichwort","Seite"],"rows":[["Fahrersitz","13"],["Fernlichtkontrolle","9"],["Fernthermometer, Kühlwasser","9"],["Frostschutz","13, 15, 34"],["Fußbremse","40"]]},{"t":"h2","text":"G"},{"t":"table","caption":"","head":["Stichwort","Seite"],"rows":[["Gangschalthebel","10"],["Gasregulierung","12"],["Geschwindigkeitstabellen","5, 6"],["Geräteschiene","18"],["Gerätezugstange, schwenkbar","18"],["Getriebe, Ansaugfilter","36"],["Getriebeausführungen","10"],["Getriebeölfilter","36"],["Getriebeölwechsel","35"],["Gruppengetriebe","10"]]},{"t":"h2","text":"H"},{"t":"table","caption":"","head":["Stichwort","Seite"],"rows":[["Handbremse","40"],["Hinterräder","43"]]},{"t":"h2","text":"K"},{"t":"table","caption":"","head":["Stichwort","Seite"],"rows":[["Keilriemen","34"],["Kombiinstrument","8"],["Kontrollelemente","8"],["Kontrolleuchte, Motoröldruck","9"],["Kontrolleuchte, Wandlergetriebeöldruck","9"],["Kraftstoff","27"],["Kraftstoffanzeiger","9"],["Kraftstoffilter","29"],["Kraftstoffsystem, Entlüften","30"],["Kraftstoffzusatzmittel","28"],["Kühler","34"],["Kühlerdruckverschluß","32"],["Kühlergrill","26"],["Kühlsystem","32"],["Kupplung, einfach, zweifach","39"]]},{"t":"h2","text":"L"},{"t":"table","caption":"","head":["Stichwort","Seite"],"rows":[["Ladekontrolleuchte","9"],["Lamellenkupplung","39"],["Lenkgetriebe","38"],["Lichtmaschine","46"],["Luftfilter","26"]]},{"t":"h2","text":"M"},{"t":"table","caption":"","head":["Stichwort","Seite"],"rows":[["Motorhaube","26"],["Motorölfilter","32"],["Motorölwechsel","31"]]}]},{"id":"p58","printed":"54","ratio":1.5456,"blocks":[{"t":"h2","text":"O"},{"t":"table","caption":"","head":["Stichwort","Seite"],"rows":[["Ölfilter, Getriebe","36"],["Ölfilter, Motor","32"],["Ölfilter, Regelhydraulik","37"],["Ölwechsel, Getriebe","35"],["Ölwechsel, Motor","31"]]},{"t":"h2","text":"P"},{"t":"table","caption":"","head":["Stichwort","Seite"],"rows":[["Prüfungen vor täglichem Arbeitsbeginn","12"]]},{"t":"h2","text":"R"},{"t":"table","caption":"","head":["Stichwort","Seite"],"rows":[["Radlager","42"],["Ratschläge","7"],["Regelhydraulik","19, 37"],["Regler für Einspritzpumpe","29"]]},{"t":"h2","text":"S"},{"t":"table","caption":"","head":["Stichwort","Seite"],"rows":[["Schaltgriff für Wandlergetriebe","11"],["Schaltschema","48"],["Scheinwerfer","45"],["Schmiermittel","25"],["Schmierplan","25"],["Sicherungen","45"],["Spannungsregler","46"],["Spurverstellung","41, 43"]]},{"t":"h2","text":"T"},{"t":"table","caption":"","head":["Stichwort","Seite"],"rows":[["Technische Einzelheiten","4"],["Thermostat","33"],["Traktormeter","8"]]},{"t":"h2","text":"U"},{"t":"table","caption":"","head":["Stichwort","Seite"],"rows":[["Unfallverhütung","16"]]},{"t":"h2","text":"V"},{"t":"table","caption":"","head":["Stichwort","Seite"],"rows":[["Vorabscheider, Luftfilter","27"],["Vorderräder","41"],["Vorderradlager","42"],["Vorspur","41"]]},{"t":"h2","text":"W"},{"t":"table","caption":"","head":["Stichwort","Seite"],"rows":[["Wandlergetriebe","10"],["Wartungszeiten","23, 25"],["Wasserfüllung für Hinterräder","14"],["Wasserpumpe","34"],["Werkzeuge","26"],["Winterbetrieb","13"]]},{"t":"h2","text":"Z"},{"t":"table","caption":"","head":["Stichwort","Seite"],"rows":[["Zapfwellen","17"],["Zugstange","18"]]}]},{"id":"p59","printed":null,"ratio":1.5455,"blocks":[{"t":"p","text":"INTERNATIONAL HARVESTER"},{"t":"h1","text":"INTERNATIONAL HARVESTER COMPANY M.B.H., NEUSS UND HEIDELBERG"}]}]};
